const attached=docs.filter(x=>String(x.subjectId||'')===String(active)||(x.parentType==='clienti'&&match(x.parentId,active))||(x.parentType==='immobili'&&siteIds.has(String(x.parentId)))||(x.parentType==='impianti'&&plantIds.has(String(x.parentId)))||(x.parentType==='apparecchiature'&&deviceIds.has(String(x.parentId)))||(x.parentType==='interventi'&&jobIds.has(String(x.parentId))));
el('profilo-documenti').innerHTML=head('Documenti',attached.length)+'<button type="button" onclick="ITEProfile.addDocument()">+ Aggiungi file</button>'+(attached.map(x=>entry(x.type||'Documento',(x.fileName||'')+' · '+(x.date||'')+(x.expires?' · Scadenza / controllo: '+x.expires:''),'<button type="button" onclick="ITEProfile.viewDoc('+JSON.stringify(x.id).replace(/"/g,'&quot;')+')">Apri documento</button>')).join('')||empty);
