const choices=['Cliente','Dipendente','Titolare','Operatore','Fornitore','Professionista','Collaboratore esterno','Subappaltatore'];let editing=null,lastDocs=[],alertRun=0;
if(!ITE.archiveReadable()){const warning=document.createElement('div');warning.className='alert-red';warning.setAttribute('role','alert');warning.textContent='ARCHIVIO NON LEGGIBILE. I dati esistenti non vengono sovrascritti. Salvataggi e backup sono bloccati: conservare i dati del browser per il recupero.';document.querySelector('main').prepend(warning)}
const base={create:ITE.create,edit:ITE.edit,save:ITE.save,cancel:ITE.cancel,render:ITE.render,remove:ITE.remove};
const rawRoles=r=>Array.isArray(r.roles)&&r.roles.length?r.roles:[r.kind||'Cliente'];
function roles(r){const result=rawRoles(r).filter(v=>v!=='Tecnico');if(!result.length&&rawRoles(r).includes('Tecnico'))result.push('Dipendente');return result}
function personnel(r){return rawRoles(r).some(v=>['Dipendente','Titolare','Tecnico','Operatore'].includes(v))}
function isTechnician(r){return r.is_technician==='1'&&personnel(r)||r.is_technician===undefined&&rawRoles(r).includes('Tecnico')}
const external=r=>roles(r).some(v=>['Collaboratore esterno','Subappaltatore'].includes(v));
function matchesRole(r,value){return !value||value==='Imprese esterne'&&external(r)||value==='Personale'&&personnel(r)||value==='Tecnici operativi'&&isTechnician(r)||roles(r).includes(value)}
function parseIds(value){if(!value)return [];const result=JSON.parse(value);if(!Array.isArray(result)||result.some(v=>typeof v!=='string'||!/^\d+$/.test(v)))throw Error('Collegamenti non validi');return [...new Set(result)]}
function validateLinks(db){if(window.ITEAgenda)ITEAgenda.validateDatabase(db);if(window.ITEOperators)ITEOperators.validateDatabase(db);for(const site of db.cantieri||[]){if(site.client_id&&!db.clienti.some(r=>String(r.id)===site.client_id))throw Error('Cliente del cantiere non presente');if(site.immobile_id&&!db.immobili.some(r=>String(r.id)===site.immobile_id&&(!site.client_id||r.client_id===site.client_id)))throw Error('Immobile del cantiere non valido');for(const key of ['professional_ids','external_ids'])for(const id of parseIds(site[key]))if(!db.clienti.some(r=>String(r.id)===id&&(key==='professional_ids'?roles(r).includes('Professionista'):external(r))))throw Error('Il cantiere richiede un soggetto con il ruolo corretto: professionista o impresa esterna')}}
function field(key,title,type='text',value='',extra=''){return '<label>'+esc(title)+'<input name="'+key+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></label>'}
function fields(row,list){return list.map(([key,label,type])=>field(key,label,type||'text',row[key]??'',key==='internal_hourly_cost'?'min="0" max="1000" step="0.01" inputmode="decimal"':'')).join('')}
function group(id,title,html){return '<fieldset id="'+id+'" class="form-wide"><legend>'+title+'</legend><div class="grid">'+html+'</div></fieldset>'}
const common=[['address','Indirizzo'],['postal_code','CAP'],['city','Comune'],['province','Provincia'],['tax_code','Codice fiscale'],['email','Email','email'],['phone','Telefono','tel']];
const business=[['company_name','Ragione sociale'],['vat','Partita IVA'],['pec','PEC','email'],['sdi','Codice destinatario / SDI'],['iban','IBAN'],['company_register','Registro imprese / REA']];
const staff=[['internal_hourly_cost','Costo orario interno per analisi cantieri (€/h, non prezzo al cliente)','number'],['job_role','Ruolo / mansione lavorativa'],['license_categories','Categorie patente'],['license_number','Numero patente'],['license_expiry','Scadenza patente','date']];
const professional=[['profession','Professione (architetto, termotecnico, ingegnere, geometra…)'],['professional_role','Incarico (progettista, direttore lavori…)'],['register_name','Albo / ordine professionale'],['register_number','Numero iscrizione'],['register_province','Provincia albo'],['professional_pec','PEC professionale','email']];
function propertyForm(row={},index=0){return '<fieldset class="property-block" data-property-id="'+esc(row.id||'')+'"><legend>Immobile / utenza '+(index+1)+'</legend><div class="grid">'+[['name','Indirizzo immobile (se diverso dalla residenza)'],['city','Comune immobile'],['province','Provincia immobile'],['foglio','Foglio'],['particella','Particella / mappale'],['subalterno','Subalterno'],['pod','POD'],['pdr','PDR']].map(([key,label])=>'<label>'+label+'<input data-property="'+key+'" value="'+esc(row[key]||'')+'" '+(['pod','pdr'].includes(key)?'maxlength="15"':'')+'></label>').join('')+'</div>'+(row.catasto?'<p class="hint">Dati catastali precedenti conservati: '+esc(row.catasto)+'</p>':'')+'</fieldset>'}
function activeRoles(){return [...$('fields').querySelectorAll('[name=roles]:checked')].map(n=>n.value)}
function updateGroups(){const selected=activeRoles(),person=selected.some(v=>['Dipendente','Titolare'].includes(v)),company=['Fornitore','Collaboratore esterno','Subappaltatore'].some(v=>selected.includes(v));$('entity-type').disabled=person;if(person)$('entity-type').value='Persona';const entity=$('entity-type').value;for(const [id,visible] of [['staff-fields',person],['client-fields',selected.includes('Cliente')],['professional-fields',selected.includes('Professionista')],['external-fields',selected.some(v=>['Collaboratore esterno','Subappaltatore'].includes(v))],['business-fields',entity==='Azienda'||company||selected.includes('Professionista')]]){const area=$(id);area.hidden=!visible;for(const input of area.querySelectorAll('input,select,textarea'))input.disabled=!visible}
const names=$('identity-fields');names.querySelector('[name=first_name]').required=entity==='Persona'&&!editing?.legacy;names.querySelector('[name=last_name]').required=entity==='Persona'&&!editing?.legacy;const companyInput=$('fields').querySelector('[name=company_name]');companyInput.required=entity==='Azienda';$('company-name-label').textContent=entity==='Azienda'?'Ragione sociale *':'Ragione sociale (se applicabile)';$('identity-hint').textContent=entity==='Azienda'?'Nome e cognome del referente, se presenti.':'Nome e cognome della persona.';$('role-doc-hint').textContent='Dopo il salvataggio, Apri scheda → Documenti per allegare '+(person?'codice fiscale, carta di identità, patente, corsi e attestati.':selected.includes('Fornitore')?'fatture e bolle / DDT.':selected.includes('Professionista')?'progetti, POS e Di.Co., collegandoli ai cantieri.':selected.some(v=>['Collaboratore esterno','Subappaltatore'].includes(v))?'visura, DURC e requisiti, con scadenza o prossimo controllo.':'i documenti del soggetto.');}
function contactEditor(id){base.cancel();const row=id===null?{}:ITE.snapshot().clienti.find(r=>r.id===id);if(!row)return;const selected=roles(row),legacy=!!row.name&&!row.first_name&&!row.last_name&&!row.company_name;editing={kind:'clienti',id,legacy};$('edit-title').textContent=id===null?'Nuova anagrafica':'Modifica anagrafica — '+row.name;
const entity=row.entity_type||(['Fornitore','Collaboratore esterno','Subappaltatore'].some(v=>selected.includes(v))?'Azienda':'Persona');
$('fields').innerHTML=group('role-fields','Tipo di anagrafica','<label>Profilo principale<select id="primary-role">'+choices.map(r=>'<option '+(r===selected[0]?'selected':'')+'>'+r+'</option>').join('')+'</select></label><div class="form-wide"><p class="hint">Una sola scheda può avere più ruoli. Cambiare il profilo principale seleziona quel ruolo; puoi poi aggiungerne altri qui.</p><div class="role-options">'+choices.map(r=>'<label><input type="checkbox" name="roles" value="'+r+'" '+(selected.includes(r)?'checked':'')+'>'+r+'</label>').join('')+'</div></div><label>Persona o azienda<select id="entity-type" name="entity_type"><option '+(entity==='Persona'?'selected':'')+'>Persona</option><option '+(entity==='Azienda'?'selected':'')+'>Azienda</option></select></label>')+
group('identity-fields','Dati anagrafici',(legacy?'<p class="hint form-wide">Nominativo precedente: '+esc(row.name)+'. Non viene diviso automaticamente: puoi indicare nome e cognome nei campi separati.</p>':'')+(rawRoles(row).includes('Tecnico')?'<p class="hint form-wide">Tecnico della versione precedente: conferma se è Dipendente oppure scegli Titolare prima di salvare.</p>':'')+'<p id="identity-hint" class="hint form-wide"></p>'+field('first_name','Nome','text',row.first_name)+field('last_name','Cognome','text',row.last_name)+fields(row,common))+
group('business-fields','Dati aziendali e fiscali',fields(row,business))+group('staff-fields','Personale: dipendente o titolare',fields(row,staff)+'<label class="form-wide"><input name="is_technician" type="checkbox" value="1" style="width:auto" '+(isTechnician(row)?'checked':'')+'> Svolge la funzione di tecnico operativo (selezionabile negli interventi)</label>')+
group('professional-fields','Professione e iscrizione all’albo',fields(row,professional))+
group('external-fields','Impresa esterna e requisiti',field('requirements','Requisiti / abilitazioni richiesti','text',row.requirements)+'<p class="hint form-wide">Visura e DURC si allegano nella scheda del soggetto. Per la visura indica il prossimo controllo; per il DURC la scadenza riportata sul documento. Gli avvisi saranno visibili in Scadenze e nei cantieri.</p>')+
'<fieldset id="client-fields" class="form-wide"><legend>Cliente: immobili, catasto e utenze</legend><p class="hint">Questi dati appartengono all’immobile. Puoi registrare più immobili; i dati non vengono duplicati nell’anagrafica della persona.</p><div id="client-properties">'+((id===null?[]:ITE.snapshot().immobili.filter(r=>String(r.client_id)===String(id))).map(propertyForm).join('')||propertyForm())+'</div><button type="button" id="add-property" class="secondary">Aggiungi altro immobile / utenza</button></fieldset>'+group('notes-fields','Note','<label class="form-wide">Note<textarea name="notes" rows="3">'+esc(row.notes||'')+'</textarea></label><p id="role-doc-hint" class="hint form-wide"></p>');
const companyLabel=$('fields').querySelector('[name=company_name]').parentElement;companyLabel.firstChild.textContent='';const span=document.createElement('span');span.id='company-name-label';companyLabel.prepend(span);
$('primary-role').addEventListener('change',()=>{for(const check of $('fields').querySelectorAll('[name=roles]'))check.checked=check.value===$('primary-role').value;if(['Fornitore','Collaboratore esterno','Subappaltatore'].includes($('primary-role').value))$('entity-type').value='Azienda';updateGroups()});for(const c of $('fields').querySelectorAll('[name=roles]'))c.addEventListener('change',updateGroups);$('entity-type').addEventListener('change',updateGroups);$('add-property').onclick=()=>{const host=$('client-properties');host.insertAdjacentHTML('beforeend',propertyForm({},host.children.length))};updateGroups();if(window.ITERouter&&ITERouter.current()!=='scheda-cliente')ITERouter.show('clienti');$('clienti').appendChild($('editor'));$('editor').hidden=false;$('editor').scrollIntoView({behavior:'smooth',block:'start'});}
function contactSave(){const ctx=editing,db=ITE.snapshot(),prior=ctx.id===null?{}:db.clienti.find(r=>r.id===ctx.id),form=new FormData($('record-form')),row={...prior};row.roles=activeRoles();if(!row.roles.length)throw Error('Seleziona almeno un ruolo.');for(const [key,value] of form)if(key!=='roles')row[key]=String(value).trim();row.entity_type=$('entity-type').value;row.is_technician=row.roles.some(v=>['Dipendente','Titolare'].includes(v))&&$('fields').querySelector('[name=is_technician]').checked?'1':'0';if(row.entity_type==='Persona'){if(!row.first_name||!row.last_name){if(!ctx.legacy)throw Error('Indica nome e cognome.');if(row.first_name||row.last_name)throw Error('Completa sia nome sia cognome.');row.name=prior.name}else row.name=(row.first_name+' '+row.last_name).trim()}else{if(!row.company_name)throw Error('Indica la ragione sociale.');row.name=row.company_name}row.kind=row.roles[0];
if(row.roles.some(v=>['Dipendente','Titolare','Tecnico','Operatore'].includes(v))&&row.internal_hourly_cost!==undefined&&row.internal_hourly_cost!==''){const cost=Number(row.internal_hourly_cost);if(!Number.isFinite(cost)||cost<0||cost>1000)throw Error('Costo orario interno non valido: indica un valore da 0 a 1000 €/h.')}else row.internal_hourly_cost='';if(row.license_expiry&&!ITEDocs.validDate(row.license_expiry))throw Error('Scadenza patente non valida.');if(db.interventi.some(j=>window.ITEOperators?ITEOperators.references(j,ctx.id):String(j.technician_id||'')===String(ctx.id))&&!(window.ITEOperators?ITEOperators.eligible(row):isTechnician(row)))throw Error('Il soggetto è assegnato a interventi: mantieni un ruolo operativo o riassegna prima le registrazioni.');
const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]/g,'');const duplicate=db.clienti.find(r=>r.id!==ctx.id&&((norm(row.tax_code)&&norm(row.tax_code)===norm(r.tax_code))||(norm(row.vat)&&norm(row.vat)===norm(r.vat))||norm(row.name)===norm(r.name)));if(duplicate)throw Error('Soggetto già presente: '+duplicate.name+'. Aggiungi i ruoli alla sua scheda.');
const propertyRows=[];if(row.roles.includes('Cliente'))for(const block of $('client-properties').children){const r={};for(const input of block.querySelectorAll('[data-property]'))r[input.dataset.property]=input.value.trim();const id=block.dataset.propertyId;if(!id&&!Object.values(r).some(Boolean))continue;if(!r.name)r.name=row.address||'';if(!r.name)throw Error('Indica l’indirizzo dell’immobile o della persona.');propertyRows.push({id:id?Number(id):null,values:r})}
ITE.commit(next=>{row.id=ctx.id??Math.max(0,...next.clienti.map(r=>r.id))+1;if(ctx.id===null)next.clienti.push(row);else next.clienti[next.clienti.findIndex(r=>r.id===ctx.id)]=row;for(const p of propertyRows){const index=next.immobili.findIndex(r=>r.id===p.id);if(p.id&&index<0)throw Error('Immobile non trovato');if(p.id&&String(next.immobili[index].client_id)!==String(row.id))throw Error('Immobile di un altro cliente');const value={...(index<0?{}:next.immobili[index]),...p.values,id:p.id??Math.max(0,...next.immobili.map(r=>r.id))+1,client_id:String(row.id)};if(index<0)next.immobili.push(value);else next.immobili[index]=value}validateLinks(next)});editing=null;base.cancel();ITE.render();refreshAlerts();}
function siteEditor(id){base.cancel();const db=ITE.snapshot(),row=id===null?{}:db.cantieri.find(r=>r.id===id);if(!row)return;editing={kind:'cantieri',id};$('edit-title').textContent=id===null?'Nuovo cantiere':'Modifica cantiere';const select=(key,label,rows)=>'<label>'+label+'<select name="'+key+'"><option value="">— Seleziona —</option>'+rows.map(r=>'<option value="'+r.id+'" '+(String(r.id)===String(row[key])?'selected':'')+'>'+esc(r.name)+'</option>').join('')+'</select></label>';const checks=(key,label,rows)=>group(key,label,'<div class="check-options form-wide">'+rows.map(r=>'<label><input type="checkbox" name="'+key+'" value="'+r.id+'" '+(parseIds(row[key]).includes(String(r.id))?'checked':'')+'> '+esc(r.name)+'</label>').join('')+'</div>');
$('fields').innerHTML=field('name','Nome / descrizione cantiere','text',row.name,'required')+field('address','Indirizzo cantiere','text',row.address)+select('client_id','Cliente',db.clienti.filter(r=>roles(r).includes('Cliente')))+select('immobile_id','Immobile del cliente',db.immobili)+checks('professional_ids','Professionisti incaricati',db.clienti.filter(r=>roles(r).includes('Professionista')||parseIds(row.professional_ids).includes(String(r.id))))+checks('external_ids','Collaboratori esterni e subappaltatori',db.clienti.filter(r=>external(r)||parseIds(row.external_ids).includes(String(r.id))))+'<p class="hint form-wide">I soggetti con DURC o visura scaduti o mancanti saranno segnalati nella scheda del cantiere. Questa demo non gestisce cancelli o autorizzazioni fisiche.</p>';
const client=$('fields').querySelector('[name=client_id]'),site=$('fields').querySelector('[name=immobile_id]');function constrain(){const previous=site.value;site.replaceChildren(new Option('— Nessun immobile —',''));for(const r of db.immobili.filter(r=>!client.value||r.client_id===client.value))site.add(new Option(r.name,String(r.id)));if([...site.options].some(o=>o.value===previous))site.value=previous}client.onchange=constrain;constrain();if(window.ITERouter)ITERouter.show('cantieri');$('cantieri').appendChild($('editor'));$('editor').hidden=false;$('editor').scrollIntoView({behavior:'smooth',block:'start'});}
function siteSave(){const {id}=editing,form=new FormData($('record-form')),row={...(ITE.snapshot().cantieri.find(r=>r.id===id)||{})};for(const key of ['name','address','client_id','immobile_id'])row[key]=String(form.get(key)||'').trim();if(!row.name)throw Error('Indica il nome del cantiere.');for(const key of ['professional_ids','external_ids'])row[key]=JSON.stringify(form.getAll(key));ITE.commit(db=>{row.id=id??Math.max(0,...db.cantieri.map(r=>r.id))+1;if(id===null)db.cantieri.push(row);else db.cantieri[db.cantieri.findIndex(r=>r.id===id)]=row;validateLinks(db)});editing=null;base.cancel();ITE.render();refreshAlerts();}
function documentTypes(r){const values=new Set(['Altro']);const rr=roles(r);if(rr.includes('Cliente'))['Codice fiscale','Carta di identità','Di.Co. elettrica','Di.Co. idrica / termica','Libretto impianto','Rapporto manutenzione','FGAS','CRITER','Fotografia tecnica'].forEach(v=>values.add(v));if(personnel(r))['Codice fiscale','Carta di identità','Patente','Corso','Attestato'].forEach(v=>values.add(v));if(rr.includes('Fornitore'))['Fattura fornitore','Bolla / DDT'].forEach(v=>values.add(v));if(rr.includes('Professionista'))['Progetto','POS','Di.Co. elettrica','Di.Co. idrica / termica','Attestato'].forEach(v=>values.add(v));if(external(r))['Visura camerale','DURC','Requisito / abilitazione','POS','Attestato'].forEach(v=>values.add(v));return [...values].filter(v=>v!=='Altro').concat('Altro')}
function pairs(row,keys){return '<dl class="data-pairs">'+keys.filter(([key])=>row[key]).map(([key,label])=>'<div><dt>'+label+'</dt><dd>'+esc(row[key])+'</dd></div>').join('')+'</dl>'}
function profile(r,rel){const rr=roles(r),siteLinks=(ITE.snapshot().cantieri||[]).filter(s=>s.client_id===String(r.id)||parseIds(s.professional_ids).includes(String(r.id))||parseIds(s.external_ids).includes(String(r.id)));let html='<h2>Scheda — '+esc(r.name)+'</h2><p>'+esc(rr.join(' · '))+(isTechnician(r)?' · Tecnico operativo':'')+'</p><button type="button" onclick="ITEProfile.edit(\'clienti\','+r.id+')">Modifica anagrafica</button>'+pairs(r,[['first_name','Nome'],['last_name','Cognome'],...common,...(r.entity_type==='Azienda'||rr.some(v=>['Fornitore','Professionista','Collaboratore esterno','Subappaltatore'].includes(v))?business:[]),...(personnel(r)?staff:[]),...(rr.includes('Professionista')?professional:[]),...(external(r)?[['requirements','Requisiti']]:[]),['notes','Note']]);
if(external(r))html+='<div class="subject-requirements" data-subject="'+r.id+'">'+requirementHtml(r,lastDocs)+'</div>';
html+='<h3>Documenti del soggetto</h3><div class="actions">'+documentTypes(r).map(type=>'<button type="button" class="secondary" data-add-subject-doc="'+r.id+'" data-doc-type="'+esc(type)+'">+ '+esc(type)+'</button>').join('')+'</div>';
if(rr.includes('Cliente'))html+=ITEHierarchy.profile(rel);
if(window.ITEAgenda)html+=ITEAgenda.customerJobs(r.id);
if(siteLinks.length)html+='<h3>Cantieri collegati</h3>'+siteLinks.map(s=>'<div class="item"><strong>'+esc(s.name)+'</strong><button data-show-site="'+s.id+'">Apri cantiere e documenti</button></div>').join('');return html;}
const today=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
const subjectOf=d=>String(d.subjectId||(d.parentType==='clienti'?d.parentId:''));
function latest(docs,id,type){return docs.filter(d=>subjectOf(d)===String(id)&&d.type===type).sort((a,b)=>(b.date||'').localeCompare(a.date||'')||b.created-a.created)[0]}
function requirementState(r,docs){return ['DURC','Visura camerale'].map(type=>{const d=latest(docs,r.id,type),now=today();if(!d)return {type,level:'red',text:'documento mancante'};if(!d.date||!ITEDocs.validDate(d.date)||!d.expires||!ITEDocs.validDate(d.expires))return {type,level:'red',text:'scadenza / controllo da indicare',doc:d};if(d.date&&d.date>now)return {type,level:'red',text:'data documento futura: verificare',doc:d};if(d.expires<now)return {type,level:'red',text:(type==='DURC'?'scaduto':'controllo da aggiornare')+' il '+d.expires,doc:d};const limit=new Date(now+'T12:00:00');limit.setDate(limit.getDate()+30);const end=limit.getFullYear()+'-'+String(limit.getMonth()+1).padStart(2,'0')+'-'+String(limit.getDate()).padStart(2,'0');return {type,level:d.expires<=end?'amber':'ok',text:'scadenza / controllo '+d.expires,doc:d}})}
function requirementHtml(r,docs){const states=requirementState(r,docs),blocked=states.some(s=>s.level==='red');return '<div class="'+(blocked?'alert-red':states.some(s=>s.level==='amber')?'alert-amber':'item')+'"><strong>'+(blocked?'ACCESSO SOSPESO / DA VERIFICARE — regola organizzativa della demo':'Scadenze registrate: verifica documentale richiesta')+'</strong><ul>'+states.map(s=>'<li>'+esc(s.type+': '+s.text)+'</li>').join('')+'</ul><small>Il controllo delle date non certifica l’idoneità dell’impresa né autorizza automaticamente l’accesso.</small></div>'}
function issues(docs){const result=[];for(const r of ITE.snapshot().clienti){if(external(r))for(const state of requirementState(r,docs))if(state.level!=='ok')result.push({subject:r,...state});if(personnel(r)&&r.license_expiry&&!latest(docs,r.id,'Patente')?.expires){const date=r.license_expiry,end=new Date(today()+'T12:00:00');end.setDate(end.getDate()+30);if(!ITEDocs.validDate(date)||new Date(date+'T12:00:00')<=end)result.push({subject:r,type:'Patente (anagrafica)',level:date<today()||!ITEDocs.validDate(date)?'red':'amber',text:'scadenza '+date})}}
const end=new Date(today()+'T12:00:00');end.setDate(end.getDate()+30);for(const d of docs){if(['Codice fiscale','Carta di identità','Patente'].includes(d.type)&&subjectOf(d)&&latest(docs,subjectOf(d),d.type)?.id!==d.id)continue;if(!d.expires||['DURC','Visura camerale'].includes(d.type)&&ITE.snapshot().clienti.some(r=>String(r.id)===subjectOf(d)&&external(r)))continue;if(!ITEDocs.validDate(d.expires)||new Date(d.expires+'T12:00:00')>end)continue;result.push({subject:ITE.snapshot().clienti.find(r=>String(r.id)===subjectOf(d)),type:d.type,doc:d,level:d.expires<today()?'red':'amber',text:'scadenza / controllo '+d.expires})}return result.sort((a,b)=>(a.level==='red'?0:1)-(b.level==='red'?0:1))}
async function refreshAlerts(){const run=++alertRun;try{const docs=await ITEDocs.listDocs();if(run!==alertRun)return;lastDocs=docs;window.ITEWorksites?.refreshFromDocs(docs);const all=issues(docs),red=all.filter(r=>r.level==='red').length;$('nav-alert-count').textContent=all.length?'('+all.length+')':'';$('home-alerts').innerHTML=all.length?'<div class="'+(red?'alert-red':'alert-amber')+'"><a class="alert-button" href="#scadenze">'+red+' verifiche urgenti · '+(all.length-red)+' scadenze vicine</a></div>':'';$('expiry-list').innerHTML=all.map(item=>'<div class="alert-'+item.level+'"><strong>'+esc(item.subject?.name||'Documento collegato')+' — '+esc(item.type)+'</strong><p>'+esc(item.text)+'</p>'+(item.subject?'<button data-open-subject="'+item.subject.id+'">Apri soggetto</button> ':'')+(item.doc?'<button data-view-doc="'+esc(item.doc.id)+'">Apri documento</button>':'')+'</div>').join('')||'<p>Nessuna scadenza o requisito incompleto rilevato nei dati registrati.</p>';for(const block of document.querySelectorAll('.subject-requirements')){const r=ITE.snapshot().clienti.find(r=>String(r.id)===block.dataset.subject);if(r)block.innerHTML=requirementHtml(r,docs)}renderSites()}catch(e){$('expiry-list').textContent='Impossibile verificare i documenti: '+e.message;$('home-alerts').innerHTML='<div class="alert-red"><a href="#scadenze">Controllo documenti non disponibile: verificare prima degli accessi.</a></div>'}}
function renderSites(){if(window.ITEWorksites){ITEWorksites.renderList();return}const db=ITE.snapshot();$('list-cantieri').innerHTML=(db.cantieri||[]).map(s=>{const professionals=parseIds(s.professional_ids).map(id=>db.clienti.find(r=>String(r.id)===id)).filter(Boolean),externals=parseIds(s.external_ids).map(id=>db.clienti.find(r=>String(r.id)===id)).filter(Boolean),docs=lastDocs.filter(d=>String(d.siteId||'')===String(s.id)||d.parentType==='cantieri'&&String(d.parentId)===String(s.id));return '<div class="item" id="cantiere-'+s.id+'"><strong>'+esc(s.name)+'</strong><p>'+esc(s.address||'')+'</p><p>Cliente: '+esc(db.clienti.find(r=>String(r.id)===s.client_id)?.name||'non collegato')+'</p><p>Professionisti: '+esc(professionals.map(r=>r.name).join(', ')||'nessuno')+'</p><button data-edit-site="'+s.id+'">Modifica cantiere</button> <button data-add-site-doc="'+s.id+'">Aggiungi progetto / POS / Di.Co. / documento</button> <button class="danger" data-delete-site="'+s.id+'">Elimina</button>'+externals.map(r=>'<h4>'+esc(r.name)+'</h4>'+requirementHtml(r,lastDocs)).join('')+'<h4>Documenti collegati ('+docs.length+')</h4>'+docs.map(d=>'<p>'+esc(d.type+' — '+d.fileName)+' <button data-view-doc="'+esc(d.id)+'">Apri</button></p>').join('')+'</div>'}).join('')||'<p class="hint">Nessun cantiere registrato.</p>'}
ITE.create=k=>{if(k==='clienti')return contactEditor(null);if(k==='cantieri')return siteEditor(null);editing=null;return base.create(k)};ITE.edit=(k,id)=>{if(k==='clienti')return contactEditor(id);if(k==='cantieri')return siteEditor(id);editing=null;return base.edit(k,id)};ITE.save=e=>{if(!editing)return base.save(e);e.preventDefault();try{if(editing.kind==='clienti')contactSave();else siteSave()}catch(error){alert(error.message)}};ITE.cancel=()=>{editing=null;return base.cancel()};ITE.render=()=>{base.render();renderSites()};ITE.remove=async(k,id)=>{try{const docs=await ITEDocs.listDocs();if(docs.some(d=>d.parentType===k&&String(d.parentId)===String(id)||k==='clienti'&&String(d.subjectId||'')===String(id)||k==='cantieri'&&String(d.siteId||'')===String(id)))return alert('Sono presenti documenti collegati: riassegnali o eliminali prima.');if(k==='clienti'&&(ITE.snapshot().cantieri||[]).some(s=>s.client_id===String(id)||parseIds(s.professional_ids).includes(String(id))||parseIds(s.external_ids).includes(String(id))))return alert('Soggetto collegato a cantieri: riassegna prima i collegamenti.');if(k==='immobili'&&(ITE.snapshot().cantieri||[]).some(s=>s.immobile_id===String(id)))return alert('Immobile collegato a un cantiere.');if(k==='cantieri'){if(!confirm('Eliminare il cantiere?'))return;ITE.commit(db=>{db.cantieri=db.cantieri.filter(s=>s.id!==id)});ITE.render();return}base.remove(k,id);refreshAlerts()}catch(e){alert('Eliminazione non eseguita: '+e.message)}};
