window.ITEContacts={roles,isTechnician,matchesRole,documentTypes,profile,refreshAlerts,validateLinks,requirementState,today};ITE.render();refreshAlerts();window.addEventListener('focus',refreshAlerts);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshAlerts()});setInterval(()=>{if(!document.hidden)refreshAlerts()},60000);
