(()=>{'use strict';
const main=document.querySelector('main'),pages=[...main.children].filter(e=>e.tagName==='SECTION'&&e.id!=='editor'),ids=new Set(pages.map(e=>e.id));let current='home',currentRoute='home',lastContacts='clienti';
const roles={'clienti-cliente':'Cliente','clienti-personale':'Personale','clienti-fornitori':'Fornitore','clienti-professionisti':'Professionista','clienti-esterni':'Imprese esterne','clienti-dipendenti':'Dipendente','clienti-titolari':'Titolare','clienti-tecnici':'Tecnici operativi','clienti-collaboratori':'Collaboratore esterno','clienti-subappaltatori':'Subappaltatore'};
const guide=document.getElementById('guida');document.getElementById('informazioni').appendChild(guide);pages.splice(pages.indexOf(guide),1);ids.delete('guida');
function normalize(route){return ids.has(route)||Object.hasOwn(roles,route)?route:'home'}
const navigation={session:crypto.randomUUID(),index:0,last:0};
const navigationBars=['inizio','fine'].map(position=>{const bar=document.createElement('div');bar.className='page-navigation';bar.dataset.position=position;bar.setAttribute('role','group');bar.setAttribute('aria-label','Navigazione '+position+' pagina');bar.innerHTML='<button type="button" data-page-history="-1" aria-label="Torna alla pagina precedente">← Indietro</button><button type="button" data-page-history="1" aria-label="Vai alla pagina successiva">Avanti →</button>';if(position==='inizio')main.prepend(bar);else main.append(bar);return bar});
function updateNavigation(){if(main.firstElementChild!==navigationBars[0])main.prepend(navigationBars[0]);if(main.lastElementChild!==navigationBars[1])main.append(navigationBars[1]);for(const bar of navigationBars){bar.querySelector('[data-page-history="-1"]').disabled=navigation.index<=0;bar.querySelector('[data-page-history="1"]').disabled=navigation.index>=navigation.last;}}
function writeNavigation(route,mode){const changing=location.hash!=='#'+route;if(changing&&mode==='push'){navigation.index++;navigation.last=navigation.index;}history[changing&&mode==='push'?'pushState':'replaceState']({...history.state,itePageNavigation:{session:navigation.session,index:navigation.index}},'','#'+route);updateNavigation();}
document.addEventListener('click',event=>{const button=event.target.closest('[data-page-history]');if(!button||button.disabled)return;const delta=Number(button.dataset.pageHistory);if(navigation.index+delta<0||navigation.index+delta>navigation.last||!abandon())return;history.go(delta);});
function announce(focus=false){updateNavigation();window.dispatchEvent(new CustomEvent('ite-pagechange',{detail:{id:current,route:currentRoute,contacts:lastContacts,focus}}))}
function show(route,mode='replace',fromUser=false,focus=fromUser){route=normalize(route);if(route==='clienti'&&!fromUser&&current==='clienti'&&Object.hasOwn(roles,currentRoute))route=currentRoute;const id=Object.hasOwn(roles,route)?'clienti':route;current=id;currentRoute=route;if(id==='clienti'){lastContacts=route;document.getElementById('role-filter').value=roles[route]||'';const overview=route==='clienti';document.getElementById('directory-categories').hidden=!overview;document.getElementById('directory-list-panel').hidden=overview;document.getElementById('directory-heading').textContent=overview?'Anagrafiche':({'clienti-cliente':'Clienti','clienti-personale':'Personale e titolari','clienti-fornitori':'Fornitori','clienti-professionisti':'Professionisti','clienti-esterni':'Imprese esterne','clienti-dipendenti':'Dipendenti','clienti-titolari':'Titolari','clienti-tecnici':'Tecnici','clienti-collaboratori':'Collaboratori esterni','clienti-subappaltatori':'Subappaltatori'}[route]||'Anagrafiche');document.getElementById('role-filter').closest('label').hidden=!overview;document.getElementById('clienti-query').value='';if(!overview)ITE.render()}
for(const page of pages)page.classList.toggle('ite-inactive',page.id!==id);document.getElementById('execution-ready').classList.toggle('ite-inactive',id!=='home');
writeNavigation(route,mode);window.scrollTo({top:0,behavior:'instant'});announce(focus)}
function abandon(){if((!document.getElementById('editor').hidden||!document.getElementById('docs-form').hidden||document.getElementById('appointment-form')?.hidden===false)&&!confirm('Uscire dal modulo? Le modifiche non salvate verranno abbandonate.'))return false;ITE.cancel();ITEDocs.hideForm();ITEDocs.closePreview();window.ITEAgenda?.cancel();return true}
document.addEventListener('click',event=>{const link=event.target.closest('a[href^="#"]');if(!link)return;const target=link.hash.slice(1);if(!ids.has(target)&&!Object.hasOwn(roles,target))return;event.preventDefault();if(target===currentRoute){announce(true);return}if(!abandon())return;show(target,'push',true);if(current==='documenti')ITEDocs.refresh()});
function fromHistory(){const entry=history.state?.itePageNavigation,previous=navigation.index;const known=entry?.session===navigation.session&&Number.isInteger(entry.index)&&entry.index>=0&&entry.index<=navigation.last;const route=normalize(location.hash.slice(1));if(known)navigation.index=entry.index;if(route===currentRoute){updateNavigation();return}if(!abandon()){if(known&&navigation.index!==previous){const delta=previous-navigation.index;navigation.index=previous;history.go(delta);}else{navigation.index=previous;writeNavigation(currentRoute,'replace');}updateNavigation();return}show(route,'replace',true);if(current==='documenti')ITEDocs.refresh()}
window.addEventListener('popstate',fromHistory);window.addEventListener('hashchange',fromHistory);
document.getElementById('role-filter').addEventListener('change',e=>{const route=Object.keys(roles).find(key=>roles[key]===e.target.value)||'clienti';show(route,'replace',true,false)});
const open=ITEProfile.open,close=ITEProfile.close;ITEProfile.open=id=>{open(id);show('scheda-cliente','push')};ITEProfile.close=()=>{close();show(lastContacts,'push')};const edit=ITE.edit;ITE.edit=(k,id)=>{if(current!=='scheda-cliente')show(k);edit(k,id)};
window.ITERouter={show,current:()=>current,route:()=>currentRoute,contacts:()=>lastContacts};document.body.classList.add('ite-routing');const initial=location.hash.slice(1);show(initial==='scheda-cliente'?'clienti':initial==='scheda-cantiere'?'cantieri':initial==='scheda-intervento'?'calendario':initial||'home');
})();


