function read(job){if(!job?.work_logs)return [];const logs=JSON.parse(job.work_logs);if(!Array.isArray(logs)||logs.some(log=>!log||typeof log.operator_id!=='string'||!/^\d+$/.test(log.operator_id)||!Number.isSafeInteger(log.duration_minutes)||(log.duration_minutes<0||log.duration_minutes===0&&job.time_tracking!=='automatic')||(log.role!==undefined&&!['Principale','Supporto'].includes(log.role)))||new Set(logs.map(log=>log.operator_id)).size!==logs.length)throw Error('Registrazioni operatori non valide.');if(logs.some(log=>log.role!==undefined)&&logs.some((log,index)=>log.role!==(index===0?'Principale':'Supporto')))throw Error('Ruoli degli operatori non validi.');return logs;}
