function clientOf(type,id,data=db()){const row=(data[type]||[]).find(r=>same(r.id,id));if(!row)return '';if(type==='clienti')return String(row.id);if(type==='cantieri'||type==='immobili')return String(row.client_id||'');if(type==='impianti')return clientOf('immobili',row.immobile_id,data);if(type==='apparecchiature')return clientOf('impianti',row.impianto_id,data);return '';}
