function validateDatabase(data){const active=new Set();for(const job of data.interventi||[]){if(job.appointment!=='1')continue;const root=clientOf(job.target_type,job.target_id,data);if(!['clienti','immobili','cantieri','apparecchiature'].includes(job.target_type)||!root||root!==job.client_id||!data.clienti.some(r=>same(r.id,root)))throw Error('Riferimento appuntamento non valido.');if(job.subject_flow==='client-site-device'){const site=job.immobile_id||'',equipment=job.apparecchiatura_id||'',worksite=job.cantiere_id||'';if(site&&clientOf('immobili',site,data)!==root)throw Error('Sede non collegata al cliente.');if(job.intervention_subject==='equipment'){if(!equipment||!site||job.target_type!=='apparecchiature'||job.target_id!==equipment||siteOf('apparecchiature',equipment,data)!==site)throw Error('Apparecchiatura non collegata alla sede.');}else if(job.intervention_subject!=='other'||equipment||!job.description?.trim()||job.target_type!==(worksite?'cantieri':site?'immobili':'clienti')||job.target_id!==(worksite||site||root))throw Error('Descrizione o riferimento di Altro non valido.');if(worksite&&!(data.cantieri||[]).some(r=>same(r.id,worksite)&&same(r.client_id,root)&&(!r.immobile_id||same(r.immobile_id,site))))throw Error('Cantiere non collegato al cliente e alla sede.');} if(!['Programmato','In corso','Chiuso'].includes(job.workflow_status)||!Number.isFinite(Date.parse(job.scheduled_start))||!Number.isFinite(Date.parse(job.scheduled_end))||Date.parse(job.scheduled_end)<=Date.parse(job.scheduled_start)||!Number.isFinite(Number(job.callout_fee))||!['ordinary','quoted','extraordinary'].includes(job.callout_policy)||(job.callout_policy==='extraordinary'?Number(job.callout_fee)<=0:Number(job.callout_fee)!==0))throw Error('Date, stato o diritto di chiamata non validi.');const assigned=assignments(job);if(!assigned.length||new Set(assigned.map(a=>a.operator_id)).size!==assigned.length||assigned.some((a,i)=>!data.clienti.some(r=>same(r.id,a.operator_id))||a.role!==(i===0?'Principale':'Supporto'))||job.technician_id!==assigned[0].operator_id)throw Error('Operatori appuntamento non validi.');const list=sessions(job),seen=new Set();for(const s of list){if(!s.id||seen.has(s.id)||!assigned.some(a=>a.operator_id===s.operator_id)||!Number.isFinite(Date.parse(s.arrived_at))||(s.departed_at&&(!Number.isFinite(Date.parse(s.departed_at))||Date.parse(s.departed_at)<Date.parse(s.arrived_at))))throw Error('Orari di accesso non validi.');seen.add(s.id);if(!s.departed_at){if(active.has(s.operator_id))throw Error('Operatore già impegnato in un intervento aperto.');active.add(s.operator_id);}}if(job.workflow_status==='Programmato'&&list.length||job.workflow_status==='Chiuso'&&(!list.length||list.some(s=>!s.departed_at)||!list.some(s=>s.operator_id===assigned[0].operator_id&&s.departed_at)))throw Error('Stato dell’intervento incoerente con gli accessi.');if(list.length&&job.started_at!==list.map(s=>s.arrived_at).sort()[0])throw Error('Ora di arrivo incoerente.');if(job.workflow_status==='Chiuso'&&job.finished_at!==list.map(s=>s.departed_at).sort().at(-1))throw Error('Ora di uscita incoerente.');const expected={...job};recalculate(expected);if(expected.workflow_status!==job.workflow_status||expected.finished_at!==(job.finished_at||''))throw Error('Stato e uscita non coerenti con gli accessi.');const normalized=j=>ITEOperators.read(j).map(l=>[l.operator_id,l.role,l.duration_minutes,l.duration_seconds]);if(JSON.stringify(normalized(job))!==JSON.stringify(normalized(expected))||(job.labor_minutes||'')!==(expected.labor_minutes||''))throw Error('Tempi operatori non coerenti con gli accessi.');}
const periods=new Map();for(const job of data.interventi||[]){if(job.appointment!=='1')continue;for(const session of sessions(job)){if(!periods.has(session.operator_id))periods.set(session.operator_id,[]);periods.get(session.operator_id).push([Date.parse(session.arrived_at),session.departed_at?Date.parse(session.departed_at):Infinity]);}}for(const list of periods.values()){list.sort((a,b)=>a[0]-b[0]);for(let i=1;i<list.length;i++)if(list[i][0]<list[i-1][1])throw Error('Accessi sovrapposti dello stesso operatore.');}}

function saveAppointment(event){event.preventDefault();try{const client=$('appointment-client').value,site=$('appointment-site').value,category=$('appointment-category').value,other=category==='other',deviceId=$('appointment-device').value,worksite=$('appointment-worksite').value,description=$('appointment-notes').value.trim(),targetSite=site==='none'?'':site,type=other?(worksite?'cantieri':targetSite?'immobili':'clienti'):'apparecchiature',id=other?(worksite||targetSite||client):deviceId,primary=$('appointment-primary').value,mins=Number($('appointment-duration').value),policy=$('appointment-policy').value,fee=policy==='extraordinary'?Number($('appointment-fee').value):0,start=new Date($('appointment-start').value);
if(!client||!person(client)||( !((person(client).roles||[person(client).kind]).includes('Cliente'))))throw Error('Seleziona il cliente.');
if(!site||(targetSite&&clientOf('immobili',targetSite)!==client))throw Error('Seleziona una sede del cliente.');
if(!category||(!other&&(!deviceId||siteOf('apparecchiature',deviceId)!==targetSite||!devicesAt(targetSite).some(r=>same(r.id,deviceId)&&'category:'+(r.category||'Apparecchiatura')===category))))throw Error('Seleziona un’apparecchiatura della sede oppure Altro.');
if(other&&!description)throw Error('Descrivi l’intervento per «Altro / nessuna apparecchiatura».');
if(worksite&&!(db().cantieri||[]).some(r=>same(r.id,worksite)&&same(r.client_id,client)&&(!r.immobile_id||same(r.immobile_id,targetSite))))throw Error('Seleziona un cantiere del cliente e della sede.');
if(!Number.isFinite(start.getTime())||!Number.isSafeInteger(mins)||mins<1||!Number.isFinite(fee)||(policy==='extraordinary'?fee<=0:fee!==0))throw Error('Controlla data, durata prevista e diritto fisso.');const assigned=[{operator_id:primary,role:'Principale'},...[...$('appointment-supports').querySelectorAll('input:checked')].map(input=>({operator_id:input.value,role:'Supporto'}))];if(!primary||assigned.some(a=>!a.operator_id||!ITEOperators.eligible(person(a.operator_id))))throw Error('Seleziona un tecnico principale e operatori validi.');if(new Set(assigned.map(a=>String(a.operator_id))).size!==assigned.length)throw Error('Un operatore non può essere assegnato due volte allo stesso appuntamento.');const conflicts=plannedConflicts(records(),{id:editingId,scheduled_start:start.toISOString(),scheduled_end:new Date(start.getTime()+mins*60000).toISOString(),assigned_operators:JSON.stringify(assigned)});if(conflicts.length){const lines=conflicts.map(job=>{const shared=assignments(job).filter(a=>assigned.some(p=>p.operator_id===a.operator_id)).map(a=>person(a.operator_id)?.name||a.operator_id).join(', ');return shared+' · '+stamp(job.scheduled_start)+' → '+stamp(job.scheduled_end)+' · '+targetName(job);});if(!confirm('Attenzione: sovrapposizione con altri appuntamenti per gli operatori assegnati.\n\n'+lines.join('\n')+'\n\nSalvare comunque questo appuntamento?'))return;}let savedId;ITE.commit(next=>{const old=editingId===null?null:next.interventi.find(r=>r.id===editingId);if(editingId!==null&&(!old||old.workflow_status!=='Programmato'))throw Error('Un intervento avviato non può essere riprogrammato.');savedId=old?.id||Math.max(0,...next.interventi.map(r=>r.id))+1;const row={...(old||{}),id:savedId,appointment:'1',time_tracking:'automatic',workflow_status:'Programmato',target_type:type,target_id:id,client_id:client,immobile_id:String(targetSite),cantiere_id:worksite,apparecchiatura_id:other?'':deviceId,subject_flow:'client-site-device',intervention_subject:other?'other':'equipment',date:localDate(start),kind:$('appointment-kind').value,description:description,technician_id:primary,assigned_operators:JSON.stringify(assigned),scheduled_start:start.toISOString(),scheduled_end:new Date(start.getTime()+mins*60000).toISOString(),callout_policy:policy,callout_fee:fee.toFixed(2),work_sessions:'[]',outcome:'Da completare'};if(old)next.interventi[next.interventi.findIndex(r=>r.id===savedId)]=row;else next.interventi.push(row);validateDatabase(next);});cancel();$('agenda-date').value=localDate(start);renderCalendar();open(savedId);message('Appuntamento salvato in calendario.');}catch(e){alert(e.message);}}
function recalculate(job){const list=sessions(job),assigned=assignments(job),primary=assigned[0].operator_id;job.started_at=list.map(s=>s.arrived_at).sort()[0]||'';const mainClosed=list.some(s=>s.operator_id===primary&&s.departed_at),closed=mainClosed&&!list.some(s=>!s.departed_at);job.workflow_status=closed?'Chiuso':list.length?'In corso':'Programmato';job.outcome=closed?'Completato':'Da completare';job.finished_at=closed?list.map(s=>s.departed_at).sort().at(-1):'';if(mainClosed){const logs=assigned.filter(a=>list.some(s=>s.operator_id===a.operator_id&&s.departed_at)).map(a=>{const seconds=list.filter(s=>s.operator_id===a.operator_id&&s.departed_at).reduce((n,s)=>n+secondsFor(s),0);return {operator_id:a.operator_id,role:a.role,duration_minutes:Math.floor(seconds/60),duration_seconds:seconds};});job.work_logs=JSON.stringify(logs);job.labor_minutes=String(logs.reduce((n,l)=>n+l.duration_minutes,0));}else{delete job.work_logs;delete job.labor_minutes;}}
function start(id){try{const operator=actor();if(!operator)throw Error('Seleziona il tuo nominativo in Calendario.');const instant=now();ITE.commit(next=>{const job=next.interventi.find(r=>r.id===Number(id));if(!job||job.appointment!=='1'||job.workflow_status==='Chiuso')throw Error('Intervento non disponibile per l’arrivo.');if(!assignments(job).some(a=>a.operator_id===operator))throw Error('Non sei assegnato a questo intervento.');if(next.interventi.some(j=>j.appointment==='1'&&sessions(j).some(s=>s.operator_id===operator&&!s.departed_at)))throw Error('Hai già un intervento aperto. Registra prima l’uscita.');const list=sessions(job);list.push({id:'s'+Date.now()+'_'+Math.random().toString(36).slice(2),operator_id:operator,arrived_at:instant,departed_at:''});job.work_sessions=JSON.stringify(list);recalculate(job);validateDatabase(next);});open(id);message('Ora di arrivo registrata.');}catch(e){alert(e.message);}}
function revisionAudit(job){if(!job.revision_audit)return [];let events;try{events=JSON.parse(job.revision_audit)}catch{throw Error('Storico revisioni non leggibile: nessuna modifica effettuata.')}if(!Array.isArray(events)||events.some(e=>!e||typeof e!=='object'||typeof e.action!=='string'||typeof e.at!=='string'))throw Error('Storico revisioni non valido: nessuna modifica effettuata.');return events;}
function revision(id){try{const operator=actor();if(!operator)throw Error('Seleziona il tuo nominativo in Calendario.');if(!confirm('Riaprire questo intervento per una revisione? La chiusura precedente rimarrà nello storico.'))return;const instant=now();ITE.commit(next=>{const job=next.interventi.find(r=>r.id===Number(id));if(!job||job.appointment!=='1'||job.workflow_status!=='Chiuso')throw Error('La revisione è disponibile solo per interventi chiusi.');if(!assignments(job).some(a=>a.operator_id===operator))throw Error('Non sei assegnato a questo intervento.');if(next.interventi.some(j=>j.appointment==='1'&&sessions(j).some(t=>t.operator_id===operator&&!t.departed_at)))throw Error('Hai già un altro intervento aperto.');const oldEnd=job.finished_at;const list=sessions(job);list.push({id:'rev'+Date.now()+'_'+Math.random().toString(36).slice(2),operator_id:operator,arrived_at:instant,departed_at:''});job.work_sessions=JSON.stringify(list);const audit=revisionAudit(job);audit.push({action:'RIAPERTURA_REVISIONE',operator_id:operator,at:instant,previous_closed_at:oldEnd});job.revision_audit=JSON.stringify(audit);recalculate(job);validateDatabase(next)});open(id);message('Intervento riaperto per revisione. Chiusura precedente conservata.');}catch(e){alert(e.message);}}
function finish(id){try{const operator=actor();if(!operator)throw Error('Seleziona il tuo nominativo in Calendario.');if(!confirm('Hai terminato il lavoro? Verrà registrata l’ora di uscita attuale.'))return;const instant=now();ITE.commit(next=>{const job=next.interventi.find(r=>r.id===Number(id));if(!job||job.appointment!=='1'||job.workflow_status==='Chiuso')throw Error('Intervento già chiuso o non disponibile.');if(!assignments(job).some(a=>a.operator_id===operator))throw Error('Non sei assegnato a questo intervento.');const list=sessions(job),session=list.find(s=>s.operator_id===operator&&!s.departed_at);if(!session)throw Error('Non hai un arrivo aperto su questo intervento.');if(Date.parse(instant)<Date.parse(session.arrived_at))throw Error('L’orologio del dispositivo precede l’arrivo: controlla data e ora.');session.departed_at=instant;job.work_sessions=JSON.stringify(list);const audit=revisionAudit(job);recalculate(job);if(job.workflow_status==='Chiuso'){const revised=audit.some(e=>e.action==='RIAPERTURA_REVISIONE');audit.push({action:revised?'CHIUSURA_DOPO_REVISIONE':'CHIUSURA_INTERVENTO',operator_id:operator,at:instant});job.revision_audit=JSON.stringify(audit)}validateDatabase(next);});open(id);message('Uscita registrata. I tempi sono stati aggiornati.');}catch(e){alert(e.message);}}
function open(id){if((!$('editor').hidden||!$('docs-form').hidden||!$('appointment-form').hidden)&&!confirm('Abbandonare il modulo non salvato?'))return;ITE.cancel();ITEDocs.hideForm();cancel();activeId=Number(id);ITERouter.show('scheda-intervento','push');detail();}
function detail(){const job=db().interventi.find(j=>j.id===activeId);if(!job||job.appointment!=='1')return;const assigned=assignments(job),operator=actor(),list=sessions(job),own=list.find(s=>s.operator_id===operator&&!s.departed_at),canStart=job.workflow_status!=='Chiuso'&&assigned.some(a=>a.operator_id===operator)&&!own;const elapsed=job.started_at?Math.floor(((job.finished_at?Date.parse(job.finished_at):Date.now())-Date.parse(job.started_at))/1000):0;$('appointment-detail').innerHTML='<h2>'+esc(job.kind+' — '+targetName(job))+'</h2><p><strong>'+esc(job.workflow_status)+'</strong></p><p>Cliente: '+esc(person(job.client_id)?.name||'—')+'</p><p>Appuntamento previsto: '+esc(stamp(job.scheduled_start))+' → '+esc(clock(job.scheduled_end))+'</p><p>'+esc(assignedName(job))+'</p><p>'+esc(job.description)+'</p><div class="panel"><p>Arrivo effettivo: <strong>'+esc(stamp(job.started_at))+'</strong></p><p>Uscita effettiva: <strong>'+esc(stamp(job.finished_at))+'</strong></p><p>Durata complessiva dall’arrivo all’uscita: '+esc(duration(elapsed))+'</p><p>'+esc(automaticSummary(job))+'</p></div><p><strong>Diritto fisso di chiamata: '+money(job.callout_fee)+'</strong> · '+(job.callout_policy==='extraordinary'?'intervento straordinario, una sola voce per intervento':job.callout_policy==='quoted'?'non applicato: intervento preventivato':'non applicato: intervento ordinario')+'</p>'+(job.callout_policy==='ordinary'?'<p>Costo prestabilito dell’intervento ordinario: da configurare nel listino.</p>':'')+'<p>Operatore sul dispositivo: '+esc(person(operator)?.name||'da selezionare in Calendario')+'</p><label>Seleziona operatore<select id="agenda-detail-actor"><option value="">— Seleziona —</option>'+db().clienti.filter(ITEOperators.eligible).map(p=>'<option value="'+p.id+'" '+(same(p.id,operator)?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select></label><div class="actions">'+(canStart?'<button type="button" data-agenda-start="'+job.id+'">Sono arrivato — apri intervento</button>':'')+(own?'<button type="button" data-agenda-finish="'+job.id+'">Ho finito — registra uscita</button>':'')+(job.workflow_status==='Chiuso'&&assigned.some(a=>a.operator_id===operator)?'<button type="button" class="secondary" data-agenda-revise="'+job.id+'">Revisiona intervento</button>':'')+(job.workflow_status==='Programmato'?'<button type="button" class="secondary" data-agenda-edit="'+job.id+'">Modifica appuntamento</button>':'')+(assigned.some(a=>a.operator_id===operator)?'<button type="button" class="secondary" data-agenda-doc="'+job.id+'">Aggiungi documento</button>':'')+'</div><h3>Accessi registrati</h3>'+(list.map(s=>'<div class="item"><strong>'+esc(person(s.operator_id)?.name||s.operator_id)+'</strong><p>Arrivo: '+esc(stamp(s.arrived_at))+' · Uscita: '+esc(stamp(s.departed_at))+'</p><p>Tempo: '+esc(duration(secondsFor(s)))+(s.departed_at?'':' · in corso')+'</p></div>').join('')||'<p class="hint">Nessun arrivo registrato.</p>');}
function report(from,to){const endDate=new Date(to+'T00:00:00');endDate.setDate(endDate.getDate()+1);const lo=new Date(from+'T00:00:00').getTime(),hi=endDate.getTime();const operators=new Map(),clients=new Map(),sites=new Map();const group=(map,id,name)=>{if(!map.has(id))map.set(id,{id,name,seconds:0,fee:0,jobs:new Set()});return map.get(id)};for(const job of db().interventi){let entries=[];if(job.appointment==='1')entries=sessions(job).filter(s=>s.departed_at).map(s=>({id:s.operator_id,seconds:Math.max(0,Math.floor((Math.min(hi,Date.parse(s.departed_at))-Math.max(lo,Date.parse(s.arrived_at)))/1000))})).filter(x=>x.seconds>0);else if(job.date>=from&&job.date<=to)entries=ITEOperators.read(job).map(l=>({id:l.operator_id,seconds:l.duration_minutes*60}));const client=job.client_id||clientOf('apparecchiature',job.apparecchiatura_id),site=job.cantiere_id;const first=job.started_at?Date.parse(job.started_at):new Date((job.date||'1900-01-01')+'T12:00:00').getTime(),fee=first>=lo&&first<hi&&(!job.appointment||job.started_at)?Number(job.callout_fee||0):0;if(!entries.length&&!fee)continue;const c=group(clients,client,person(client)?.name||'Cliente non collegato'),s=site?group(sites,site,db().cantieri.find(r=>same(r.id,site))?.name||'Cantiere non presente'):null;c.fee+=fee;if(s)s.fee+=fee;c.jobs.add(job.id);if(s)s.jobs.add(job.id);for(const entry of entries){const op=group(operators,entry.id,person(entry.id)?.name||'Operatore non presente');op.seconds+=entry.seconds;op.jobs.add(job.id);c.seconds+=entry.seconds;if(s)s.seconds+=entry.seconds;}}return {operators:[...operators.values()],clients:[...clients.values()],sites:[...sites.values()]};}
function renderReport(){const from=$('agenda-report-from').value,to=$('agenda-report-to').value;if(!from||!to||from>to){$('agenda-report').textContent='Seleziona un periodo valido.';return;}try{const data=report(from,to),table=(title,rows,fees)=>'<h3>'+title+'</h3><div class="agenda-table"><table><thead><tr><th>Nominativo</th><th>Interventi</th><th>Ore-operatore</th>'+(fees?'<th>Diritti chiamata</th>':'')+'</tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(r.name)+'</td><td>'+r.jobs.size+'</td><td>'+duration(r.seconds)+'</td>'+(fees?'<td>'+money(r.fee)+'</td>':'')+'</tr>').join('')+'</tbody></table></div>'; $('agenda-report').innerHTML=table('Per operatore',data.operators,false)+table('Per cliente',data.clients,true)+table('Per cantiere',data.sites,true);}catch(e){$('agenda-report').textContent='Riepilogo non disponibile: '+e.message;}}
function customerJobs(id){const jobs=records().filter(j=>same(j.client_id,id));return '<h3>Appuntamenti e accessi ('+jobs.length+')</h3><button type="button" data-agenda-client="'+id+'">+ Nuovo appuntamento</button>'+jobs.map(card).join('');}
const originalCreate=ITE.create,originalEdit=ITE.edit,originalAdd=ITEProfile.add,originalRemove=ITE.remove,originalRender=ITE.render,originalReferences=ITEOperators.references;
ITE.create=kind=>kind==='interventi'?newAppointment():originalCreate(kind);
ITEProfile.add=(kind,id=null)=>kind==='interventi'?newAppointment('apparecchiature',id||''):originalAdd(kind,id);
ITE.edit=(kind,id)=>{const job=kind==='interventi'?db().interventi.find(r=>r.id===id):null;if(job?.appointment==='1')return open(id);return originalEdit(kind,id)};
ITEOperators.references=(job,id)=>originalReferences(job,id)||(job.appointment==='1'&&assignments(job).some(a=>same(a.operator_id,id)));
ITE.remove=async(kind,id)=>{if(kind==='interventi'){const job=db().interventi.find(r=>r.id===id);if(job?.appointment==='1'&&sessions(job).length)return alert('Intervento con accessi registrati: conserva lo storico.');}const keys={clienti:'client_id',immobili:'immobile_id',cantieri:'cantiere_id'};if(keys[kind]&&records().some(j=>same(j[keys[kind]],id)))return alert('Riferimento collegato ad appuntamenti: conserva o riassegna i collegamenti.');return originalRemove(kind,id)};
ITE.render=()=>{originalRender();renderCalendar();if(ITERouter.current()==='scheda-intervento')detail();};
