(()=>{'use strict';
const current='3.0.73',endpoint='./version.json';
let checking=false;
function busy(){return window.ITECommerce?.busy?.()||['editor','docs-form','appointment-form','warehouse-editor'].some(id=>{const e=document.getElementById(id);return e&&!e.hidden})}
function banner(text,canReload){
 let b=document.getElementById('ite-version-notice');
 if(!b){b=document.createElement('aside');b.id='ite-version-notice';b.setAttribute('role','status');b.style.cssText='position:sticky;top:0;z-index:1000;background:#e8f4ff;color:#173451;border-bottom:2px solid #285b84;padding:12px 18px;font:15px -apple-system,sans-serif';document.body.prepend(b)}
 b.replaceChildren();const label=document.createElement('strong');label.textContent=text;b.append(label);
 if(canReload){const action=document.createElement('button');action.type='button';action.textContent='Aggiorna adesso';action.style.cssText='margin-left:12px;background:#285b84;color:#fff;border:0;border-radius:7px;padding:8px';action.onclick=async()=>{if(busy()){alert('Prima salva o annulla il modulo aperto.');return}
 if(!window.ITE?.archiveReadable?.()||!window.ITE?.validate?.(window.ITE.snapshot())){alert('Archivio non leggibile o incoerente. Aggiornamento bloccato: non cancellare i dati, contatta assistenza.');return}
 const data=window.ITE.snapshot();for(const [collection,ref,parent] of [['immobili','client_id','clienti'],['impianti','immobile_id','immobili'],['apparecchiature','impianto_id','impianti']]){for(const item of data[collection]||[]){if(item[ref]&&!(data[parent]||[]).some(p=>String(p.id)===String(item[ref]))){alert('Collegamento mancante in '+collection+'. Aggiornamento bloccato: verifica l’archivio.');return}}}
 if(!confirm('Prima di aggiornare scarichiamo il backup completo, compresi gli allegati. Procedere?'))return;
 action.disabled=true;action.textContent='Preparo backup…';
 try{const ok=await window.ITEBackup.download();if(!ok){alert('Backup non completato. Aggiornamento bloccato.');return}
 if(!confirm('Controlla nell’app File/Download che il backup completo sia stato salvato. Confermi di avere il file al sicuro?'))return;
 if(window.ITEHistory)await ITEHistory.beforeUpdate();
 const u=new URL(location.href);u.searchParams.set('ite_version',String(Date.now()));location.replace(u.toString());
 }catch(e){alert('Aggiornamento fermato: '+e.message)}finally{action.disabled=false;action.textContent='Aggiorna adesso'}};b.append(action)}
}
async function check(){
 if(checking||!navigator.onLine)return;checking=true;
 try{const response=await fetch(endpoint+'?t='+Date.now(),{cache:'no-store'});if(!response.ok)throw Error('Versione non disponibile');
 const info=await response.json();if(!/^\d+\.\d+\.\d+$/.test(info.version||''))return;
 const num=s=>s.split('.').map(Number),a=num(info.version),b=num(current);const newer=a.some((v,i)=>v!==b[i]&&a.slice(0,i).every((x,j)=>x===b[j])&&v>b[i]);
 if(newer)banner('È disponibile I.T.E. '+info.version+'. Salva il lavoro corrente prima di aggiornare.',true);
 }catch(e){/* Una verifica fallita non deve bloccare il gestionale. */}finally{checking=false}
}
window.addEventListener('pageshow',check);document.addEventListener('visibilitychange',()=>{if(!document.hidden)check()});window.addEventListener('online',check);check();
})();

