const processFor=d=>processes.find(p=>p.id!=='tutti'&&p.types.includes(d.type))||processes.at(-1);
function processGuide(){const p=processes.find(p=>p.id===activeProcess)||processes[0];$('import-guide').innerHTML='<h3>'+esc(p.name)+' · guida di importazione</h3><ol>'+p.steps.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ol><p class="hint">'+esc(p.hint)+'</p>';$('import-processes').innerHTML=processes.map(p=>'<button type="button" data-process="'+p.id+'" aria-pressed="'+(p.id===activeProcess)+'">'+esc(p.name)+' <span>'+state.documents.filter(d=>p.id==='tutti'||p.types.includes(d.type)).length+'</span></button>').join('');}
function selectProcess(key){if(!processes.some(p=>p.id===key))return;readQueue();activeProcess=key;$('import-category').value='';processGuide();render();}
function folderLevels(d){const c=ITE.snapshot(),client=c.clienti.find(x=>same(x.id,d.clientId||d.subjectId)),site=c.cantieri.find(x=>same(x.id,d.siteId));return [processFor(d).name,d.type,/^\d{4}-\d{2}-\d{2}$/.test(d.date)?d.date.slice(0,4):'Anno da verificare',client?.name||(nonFinancial(d)?'Azienda / da collegare':d.party?.name)||'Soggetto da collegare',site?.name||'Senza cantiere',...(String(d.folder||'').trim()?[d.folder.trim()]:[])];}
function archiveFolders(rows,depth=0){if(!rows.length)return '<p class="hint">Nessun documento in questa categoria.</p>';const groups=new Map();for(const d of rows){const name=d.type==='Articoli'?'Listini e articoli':d.type==='Da verificare'?'Da classificare':d.type;if(!groups.has(name))groups.set(name,[]);groups.get(name).push(d)}return [...groups].sort(([a],[b])=>a.localeCompare(b,'it')).map(([name,items])=>'<details class="import-folder-level" open><summary>'+esc(name)+' <small>('+items.length+')</small></summary>'+docList(items)+'</details>').join('');}
function automaticHints(d){const hints=[];if(nonFinancial(d)){if(['POS','PSC'].includes(d.type)&&!d.siteId)hints.push('Collega il cantiere per ritrovare questo documento nella relativa scheda.');if(!d.date)hints.push('Controlla la data riportata nell’originale.');if(!d.number)hints.push('Puoi usare il titolo originale come riferimento.');}if(!d.folder)hints.push('Sottocartelle automatiche: '+folderLevels(d).slice(0,3).join(' / '));return hints;}
function normalizeWords(v){return String(v||'').normalize('NFKD').replace(/[^\x00-\x7F]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();}
async function documentLayoutKey(counterparty,text){let s=normalizeWords(text).slice(0,1200);s=s.replace(/\b\d+(?:[.,/]\d+)*\b/g,'#').replace(/\s+/g,' ').trim();return hash(new TextEncoder().encode(normalizeWords(counterparty).toUpperCase()+'|'+s.slice(0,500)));}
