function catalogNorm(v){return String(v??'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function catalogKey(brand,code){return catalogNorm(brand)+'|'+String(code??'').normalize('NFKC').trim().toUpperCase()}
