function windowsDetectHeader(rows){let best=null;rows.slice(0,100).forEach((row,i)=>{try{const mapping=windowsHeaderMap(row);if(mapping.code!==undefined&&mapping.description!==undefined){const score=Object.keys(mapping).length+2*['cost','sale','price'].filter(k=>mapping[k]!==undefined).length;if(!best||score>best.score)best={score,index:i,mapping}}}catch(_){}});return best}
