function entityMatch(p,core){const vat=tax(p.vat),cf=tax(p.tax_code),byId=core.clienti.filter(r=>(vat&&tax(r.vat)===vat)||(cf&&tax(r.tax_code)===cf));if(byId.length>1)return {conflict:'Più anagrafiche condividono CF/P.IVA'};if(byId.length===1){const r=byId[0];if(vat&&r.vat&&tax(r.vat)!==vat||cf&&r.tax_code&&tax(r.tax_code)!==cf)return {conflict:'Identificativi fiscali discordanti'};return {row:r}}const names=core.clienti.filter(r=>norm(r.name)===norm(p.name)&&p.name);if(names.length>1)return {conflict:'Omonimi: scegli il soggetto corretto'};if(names.length===1){if((vat&&names[0].vat&&tax(names[0].vat)!==vat)||(cf&&names[0].tax_code&&tax(names[0].tax_code)!==cf))return {conflict:'Nome già presente con identificativi fiscali diversi'};return {row:names[0]}}return {row:null}}
function partyConflicts(p,row){if(!row)return [];return Object.keys(p).filter(k=>p[k]&&row[k]&&norm(p[k])!==norm(row[k])).map(k=>k+': presente «'+row[k]+'», importato «'+p[k]+'»')}
function readiness(d){if(duplicate(d))return ['Documento già importato: verrà saltato'];if(d.type==='Da verificare')return [];if(nonFinancial(d))return [...(!d.number?['Titolo / riferimento mancante']:[]),...(!d.date?['Data documento mancante']:[]),...(d.due&&d.date&&d.due<d.date?['La scadenza precede la data del documento']:[])];if(d.type==='Anagrafiche')return d.structured?d.contacts.flatMap(p=>{try{importedRoles(p)}catch(error){return [error.message]}const m=entityMatch(p,ITE.snapshot());return !p.name?['Riga anagrafica senza nominativo']:m.conflict?[p.name+': '+m.conflict]:partyConflicts(p,m.row).map(c=>p.name+': '+c)}):['Tabella dati assente'];if(d.type==='Articoli')return !d.lines.length?['Nessun articolo estratto: non è possibile registrare una tabella vuota.']:!d.structured?['Tabella dati assente']:d.catalogSummary&&!d.catalogSummary.valid?['Nessuna riga valida: '+[...new Set(d.lines.flatMap(l=>l.errors||[]))].slice(0,5).join(' · ')]:[];const issues=[];if(!d.number)issues.push('Numero documento mancante');if(!d.date)issues.push('Data documento mancante');if(!d.party?.name&&!d.subjectId)issues.push('Soggetto non identificato');if(/Fattura|Nota credito|Proforma/.test(d.type)&&(!Number.isFinite(d.total)||d.total<0)&&!d.type.startsWith('Nota credito'))issues.push('Totale da verificare');const m=entityMatch(d.party||{},ITE.snapshot());if(m.conflict&&!d.subjectId)issues.push(m.conflict);return issues}
function drawQueue(){prepareCatalogBatch();queue.forEach((d,i)=>{d.sourceIndex=d.sourceIndex??i});const core=ITE.snapshot();$('import-queue').innerHTML=queue.map((d,i)=>{const issues=readiness(d),m=entityMatch(d.party||{},core),conflicts=partyConflicts(d.party||{},m.row),dup=duplicate(d);if(nonFinancial(d)&&!d.tableRows)return technicalCard(d,i,dup,issues,core);if(d.type==='Articoli'||d.tableRows)return articleQueueCard(d,i,dup,issues,core);return '<details class="panel" data-queue="'+i+'" '+(i===0?'open':'')+'><summary><b>'+esc(d.sourceName)+' · '+esc(d.type)+'</b> '+(dup?'— già presente':'')+'</summary><label><input class="commerce-check" data-q="selected" type="checkbox" '+(d.selected&&!dup?'checked':'')+' '+(dup?'disabled':'')+'> Importa questa scheda</label><div class="grid"><label>Categoria<select data-q="type">'+types.map(t=>'<option '+(t===d.type?'selected':'')+'>'+esc(t)+'</option>').join('')+'</select></label>'+['number','date','net','tax','total','due'].map(k=>'<label>'+({number:'Numero / riferimento',date:'Data',net:'Imponibile (€)',tax:'IVA (€)',total:'Totale (€)',due:'Scadenza'}[k])+'<input data-q="'+k+'" type="'+(['date','due'].includes(k)?'date':['net','tax','total'].includes(k)?'number':'text')+'" step="any" value="'+esc(d[k]??'')+'"></label>').join('')+'</div><details><summary>Soggetto e dati estratti</summary><div class="grid">'+Object.keys(blank().party).map(k=>'<label>'+esc(({name:'Nominativo / ragione sociale',vat:'P.IVA',tax_code:'Codice fiscale',address:'Indirizzo',city:'Comune',province:'Provincia',postcode:'CAP',phone:'Telefono',email:'Email',pec:'PEC',recipient_code:'Codice destinatario'})[k])+'<input data-party="'+k+'" value="'+esc(d.party?.[k]||'')+'"></label>').join('')+'</div><p>'+d.lines.length+' righe articolo · '+d.contacts.length+' anagrafiche</p>'+(d.contacts.length?'<details><summary>Anteprima anagrafiche e ruoli</summary>'+d.contacts.map(p=>'<div class="item"><strong>'+esc(p.name)+'</strong><p>'+esc(p.role||'Cliente')+' · '+esc(p.vat||p.tax_code||'Identificativo fiscale assente')+'</p><p>'+esc([p.professional_role,p.register_name,p.register_number,p.job_role].filter(Boolean).join(' · '))+'</p></div>').join('')+'</details>':'')+(d.lines.length?'<details><summary>Righe estratte</summary>'+d.lines.map(l=>'<p>'+esc(l.code)+' · '+esc(l.description)+' · '+esc(l.quantity??'')+' '+esc(l.unit||'')+' · '+cash(l.price)+'</p>').join('')+'</details>':'')+'</details><div class="grid"><label>Soggetto già presente (facoltativo)<select data-q="subjectId">'+opt(core.clienti,d.subjectId)+'</select></label><label>Cliente dei lavori<select data-q="clientId">'+opt(core.clienti.filter(p=>ITEContacts.roles(p).includes('Cliente')),d.clientId)+'</select></label><label>Sede / immobile<select data-q="propertyId">'+opt(core.immobili.filter(p=>!d.clientId||same(p.client_id,d.clientId)),d.propertyId)+'</select></label><label>Cantiere<select data-q="siteId">'+opt(core.cantieri.filter(s=>!d.clientId||same(s.client_id,d.clientId)),d.siteId)+'</select></label><label>Impianto<select data-q="plantId">'+opt(core.impianti.filter(p=>d.propertyId&&same(p.immobile_id,d.propertyId)),d.plantId)+'</select></label><label>Apparecchiatura<select data-q="deviceId">'+opt(core.apparecchiature.filter(p=>d.plantId&&same(p.impianto_id,d.plantId)),d.deviceId,r=>[r.brand,r.model,r.serial].filter(Boolean).join(' '))+'</select></label><label>Intervento<select data-q="jobId">'+opt(core.interventi.filter(p=>d.clientId&&same(p.client_id,d.clientId)),d.jobId,r=>[r.date,r.kind,r.description].filter(Boolean).join(' '))+'</select></label></div>'+(d.seller?'<p class="hint">Emittente: '+esc(d.seller.name)+' · '+esc(d.seller.vat)+'<br>Destinatario: '+esc(d.buyer?.name)+' · '+esc(d.buyer?.vat)+'</p>':'')+financialDetails(d)+'<p class="hint">'+esc([...d.notes,...issues].join(' · '))+'</p>'+(conflicts.length?'<div class="alert-amber">Dati diversi già presenti: '+esc(conflicts.join(' · '))+'. Restano conservati; i valori importati rimangono nel documento.</div>':'')+'<label><input class="commerce-check" data-q="reviewed" type="checkbox" '+(d.reviewed?'checked':'')+'> Ho verificato i dati e gli eventuali conflitti indicati</label>'+(d.text?'<details><summary>Testo letto dal documento</summary><pre class="commerce-text">'+esc(d.text)+'</pre></details>':'')+'</details>'}).join('');for(const box of $('import-queue').querySelectorAll('[data-queue]')){const i=Number(box.dataset.queue),d=queue[i];if(!nonFinancial(d)||d.tableRows)box.insertAdjacentHTML('beforeend',learningControls(d,i));}$('import-apply').disabled=!queue.length;}
function readQueue(){for(const box of $('import-queue').querySelectorAll('[data-queue]')){const d=queue[Number(box.dataset.queue)];for(const el of box.querySelectorAll('[data-q]')){const k=el.dataset.q;d[k]=el.type==='checkbox'?el.checked:['net','tax','total'].includes(k)?num(el.value):el.value}for(const el of box.querySelectorAll('[data-party]'))d.party[el.dataset.party]=el.value.trim();for(const el of box.querySelectorAll('[data-guide]')){d.guide=d.guide||{};d.guide[el.dataset.guide]=el.type==='checkbox'?el.checked:el.value.trim()}}}
function upsertParty(core,p,role,explicitId,next){if(!p.name&&!explicitId)throw Error('Nominativo del soggetto mancante');const match=explicitId?{row:core.clienti.find(r=>same(r.id,explicitId))}:entityMatch(p,core);if(match.conflict)throw Error(match.conflict);let row=match.row;if(explicitId&&!row)throw Error('Soggetto selezionato non trovato');if(row){if(p.vat&&row.vat&&tax(p.vat)!==tax(row.vat)||p.tax_code&&row.tax_code&&tax(p.tax_code)!==tax(row.tax_code))throw Error('CF/P.IVA non corrispondono al soggetto selezionato');const previous=copy(row),conflicts=partyConflicts(p,row);for(const [k,v] of Object.entries(p))if(v&&!row[k])row[k]=String(v);row.roles=[...new Set([...ITEContacts.roles(row),role])];if(JSON.stringify(previous)!==JSON.stringify(row))audit(next,'COMPLETA_ANAGRAFICA',{subjectId:row.id,previous,conflicts});}else{row={id:Math.max(0,...core.clienti.map(r=>r.id))+1,...Object.fromEntries(Object.entries(p).map(([k,v])=>[k,String(v||'')])),kind:role,roles:[role]};core.clienti.push(row);audit(next,'CREA_ANAGRAFICA',{subjectId:row.id})}return String(row.id)}
function upsertWindowsArticle(next,line,supplierId,sourceId){
 if(line.errors?.length)return '';const matches=next.articles.filter(a=>catalogKey(a.brand,a.code)===catalogKey(line.brand,line.code));if(matches.length>1)throw Error('Identità duplicata: '+line.brand+' '+line.code);let a=matches[0];if((a?.id||'')!==(line.beforeId||''))throw Error('Articolo modificato dopo l’anteprima: rigenera il listino.');const prices=line.prices||{},previous=a?copy(a):null;
 if(!a){a={id:id('art'),code:String(line.code),description:line.description,brand:line.brand,model:line.model||'',category:line.category||'',unit:line.unit||'PZ',kind:'Materiale',price:null,priceRole:'',costPrice:null,salePrice:null,supplierId:supplierId||'',created:when(),sources:[],priceHistory:[]};next.articles.push(a)}else for(const k of ['category','unit','model'])if(!a[k]&&line[k])a[k]=line[k];
 for(const [field,value] of Object.entries(prices)){const key=field==='cost'?'costPrice':'salePrice',old=a[key]??null;if(old!==value){a.priceHistory=[...(a.priceHistory||[]),{at:when(),field,price:value,previous:old,sourceId}];a[key]=value;}}
 if(a.salePrice!==null&&a.salePrice!==undefined){a.price=a.salePrice;a.priceRole='sale'}else if(a.costPrice!==null&&a.costPrice!==undefined){a.price=a.costPrice;a.priceRole='cost'}
 a.sources=[...new Set([...(a.sources||[]),sourceId])];a.updated=when();audit(next,previous?'AGGIORNA_PREZZI_CATALOGO':'NUOVO_ARTICOLO_CATALOGO',{articleId:a.id,previous,prices:copy(prices),sourceId});return a.id;
}
function prepareCatalogBatch(){const seen=new Map();for(const d of queue)if(d.type==='Articoli')prepareWindowsCatalog(d);for(const d of queue.filter(x=>x.type==='Articoli'&&x.selected&&!duplicate(x)))for(const l of d.lines){const key=catalogKey(l.brand,l.code),old=seen.get(key);if(old&&old.d!==d){const equal=['description','unit','model','category','prices'].every(k=>JSON.stringify(old.line[k])===JSON.stringify(l[k]));l.errors.push(equal?'Duplicato identico nel lotto.':'Duplicato con dati discordanti nel lotto.');if(!equal)old.line.errors.push('Duplicato con dati discordanti nel lotto.')}else if(!old)seen.set(key,{d,line:l})}for(const d of queue.filter(x=>x.type==='Articoli'))d.catalogSummary={valid:d.lines.filter(l=>!l.errors.length).length,blocked:d.lines.filter(l=>l.errors.length).length,new:d.lines.filter(l=>!l.errors.length&&l.action==='NUOVO').length,updated:d.lines.filter(l=>!l.errors.length&&l.action==='AGGIORNA').length};}

function upsertArticle(next,line,supplierId,sourceId){if(line.catalog)return upsertWindowsArticle(next,line,supplierId,sourceId);if(!line.code||!line.description)return '';const found=next.articles.filter(a=>codeKey(a.code)===codeKey(line.code)&&same(a.supplierId,supplierId));if(found.length>1)throw Error('Articolo ambiguo: '+line.code);let a=found[0];const price=Number.isFinite(line.price)&&line.price>=0?line.price:null;if(!a){a={id:id('art'),code:line.code,description:line.description,brand:line.brand||'',model:line.model||'',unit:line.unit||'pz',price,kind:'Da verificare',supplierId,created:when(),sources:[sourceId],priceHistory:[{at:when(),price,sourceId}]};next.articles.push(a)}else{a.sources=[...new Set([...(a.sources||[]),sourceId])];if(price!==a.price){a.priceHistory=[...(a.priceHistory||[]),{at:when(),price,sourceId}];audit(next,'PREZZO_ARTICOLO_DA_VERIFICARE',{articleId:a.id,current:a.price,imported:price})}for(const k of ['brand','model','unit'])if(!a[k]&&line[k])a[k]=line[k]}return a.id}
async function applyQueue(){if(processing)throw Error('Attendi l’analisi.');readQueue();const selected=queue.filter(d=>d.selected&&!duplicate(d));if(!selected.length)throw Error('Nessun nuovo documento selezionato');for(const d of selected){if(d.rememberRule&&!d.reviewed)throw Error('Per ricordare una regola spunta prima «Ho verificato».');const issues=readiness(d);if(issues.length&&!(d.type==='Anagrafiche'&&d.reviewed&&issues.every(v=>v.includes('presente «'))))throw Error(d.sourceName+': '+issues.join(' · '));if(d.type!=='Da verificare'&&!d.reviewed&&(!d.structured||d.notes.length||partyConflicts(d.party||{},entityMatch(d.party||{},ITE.snapshot()).row).length))throw Error('Verifica la scheda '+d.sourceName+' e spunta «Ho verificato».')}
 const catalogs=selected.filter(d=>d.type==='Articoli');if(catalogs.length&&!confirm('Importare '+catalogs.reduce((n,d)=>n+(d.catalogSummary?.valid||0),0)+' righe valide e aggiornare i prezzi per marca + codice? '+catalogs.reduce((n,d)=>n+(d.catalogSummary?.blocked||0),0)+' righe bloccate resteranno escluse. Descrizioni storiche, documenti e giacenze restano conservati.'))return;await ITEHistory.create('Prima importazione documenti');let added=0,skipped=0;await mutate((next,core)=>{const local=[];for(const item of selected){const d=copy(item);if(d.type==='Articoli'&&d.catalogPreparedRevision!==next.revision)throw Error('Archivio modificato dopo l’anteprima: rigenera l’anteprima del listino.');if(duplicate(d,next,local)){skipped++;continue}const existing=d.existingId?next.documents.find(x=>x.id===d.existingId):null;if(existing&&next.movements.some(m=>m.documentId===existing.id)&&['type','number','date','party'].some(k=>JSON.stringify(existing[k])!==JSON.stringify(d[k])))throw Error('Documento già usato per il magazzino: conserva i dati originari e registra una rettifica motivata.');if(existing)audit(next,'REVISIONE_DATI_IMPORTATI',{documentId:existing.id,previous:copy(existing)});if(!next.files.some(f=>f.id===d.fileId))next.files.push(copy(d.file));
 if(nonFinancial(d))iteRegisterGuide(d,core,next);
 if(d.type==='Anagrafiche'){d.subjectIds=[];for(const p of d.contacts){let subjectId='';for(const role of importedRoles(p))subjectId=upsertParty(core,p,role,'',next);d.subjectIds.push(subjectId)}}
 else if(d.type!=='Da verificare'&&d.type!=='Articoli'&&!nonFinancial(d)){const role=/acquisto|DDT ricevuto/.test(d.type)?'Fornitore':'Cliente';d.subjectId=upsertParty(core,d.party,role,d.subjectId,next);if(role==='Cliente'&&!d.clientId)d.clientId=d.subjectId;}
 if(d.type==='Articoli'&&d.subjectId)upsertParty(core,{},'Fornitore',d.subjectId,next);const supplierId=/acquisto|DDT ricevuto/.test(d.type)||d.type==='Articoli'?d.subjectId:'';if(d.type==='Articoli'||supplierId)for(const line of d.lines)if(!line.catalog||!line.errors?.length)line.articleId=upsertArticle(next,line,supplierId,d.id);
 rememberRule(next,d);d.folder=String(d.folder||'').trim();if(d.folder.length>80)throw Error('Sottocartella troppo lunga.');delete d.rememberRule;delete d.learningSuggestion;d.status=d.type==='Da verificare'?'Da verificare':'Registrato';d.paymentStatus=d.paymentStatus||'Da verificare';d.assignmentStatus=d.siteId||d.jobId?'Collegato':'Da collegare';d.created=existing?.created||when();d.updated=when();d.batchId=currentBatch;d.importedArticleCount=d.lines.filter(l=>l.articleId).length;delete d.tableRows;delete d.mapping;delete d.mappingHeader;delete d.previewPage;delete d.file;delete d.selected;delete d.existingId;delete d.reviewed;delete d.guide;if(existing){d.id=existing.id;next.documents[next.documents.findIndex(x=>x.id===existing.id)]=d}else next.documents.push(d);local.push(d);added++;audit(next,'IMPORTA_DOCUMENTO',{documentId:d.id,type:d.type,fileId:d.fileId})}
 next.batches.push({id:currentBatch,at:when(),summary:added+' schede registrate · '+skipped+' duplicati saltati',documentIds:local.map(d=>d.id)});});queue=[];drawQueue();say('Importazione completata: '+added+' schede registrate. Originali conservati e collegamenti registrati; nessun movimento di magazzino o incasso creato automaticamente.');}
async function editDocument(docId){await ready;const d=state.documents.find(d=>d.id===docId);if(!d)return;if(queue.length&&!confirm('Sostituire l’anteprima aperta?'))return;queue=[{...copy(d),file:copy(state.files.find(f=>f.id===d.fileId)),existingId:d.id,selected:true,reviewed:false,notes:[...(d.notes||[]),'Modifica tracciata: originale conservato.']}];currentBatch=id('batch');ITERouter.show('importazioni','push');drawQueue();$('import-queue').scrollIntoView({block:'start'})}
async function stockDocument(docId){await ready;const d=state.documents.find(d=>d.id===docId);if(!d||!['DDT ricevuto','Fattura acquisto'].includes(d.type)||d.status!=='Registrato')throw Error('Documento non disponibile per il carico');if(state.movements.some(m=>m.documentId===d.id))throw Error('Questo documento ha già generato movimenti. Usa una rettifica motivata.');if(d.type==='DDT ricevuto'&&state.documents.some(x=>x.type==='Fattura acquisto'&&same(x.subjectId,d.subjectId)&&x.ddtRefs.some(ref=>norm(ref.number)===norm(d.number)&&(!ref.date||ref.date===d.date))&&state.movements.some(m=>m.documentId===x.id)))throw Error('Fornitura già caricata dalla fattura collegata: nessun secondo carico dal DDT.');if(d.type==='Fattura acquisto'){const receipts=state.documents.filter(x=>x.type==='DDT ricevuto'&&same(x.subjectId,d.subjectId)&&state.movements.some(m=>m.documentId===x.id));if(receipts.some(x=>d.ddtRefs.some(ref=>norm(ref.number)===norm(x.number)&&(!ref.date||ref.date===x.date))))throw Error('DDT collegato già caricato: la fattura non genera un secondo carico.');if(!confirm('Carico da fattura: verifica che il materiale non sia già stato caricato con un DDT o un movimento manuale. Confermi che questa è una fornitura non ancora caricata?'))return}
 const lines=d.lines.filter(l=>l.articleId&&Number.isFinite(l.quantity)&&l.quantity>0);if(!lines.length)throw Error('Nessuna riga materiale con codice e quantità riconosciuti. Completa gli articoli o registra un movimento manuale.');if(lines.some(l=>state.articles.find(a=>a.id===l.articleId)?.kind!=='Materiale'))throw Error('Verifica prima gli articoli nel Magazzino e imposta «Materiale» sulle righe da caricare.');if(!confirm('Registrare il carico di '+lines.length+' righe materiali del documento '+d.number+'?'))return;await ITEHistory.create('Prima carico da documento');await mutate(next=>{if(next.movements.some(m=>m.documentId===docId))throw Error('Documento già caricato');for(const l of lines)next.movements.push({id:id('mov'),articleId:l.articleId,quantity:l.quantity,date:d.date,reason:'Carico da '+d.type+' '+d.number,siteId:d.siteId||'',documentId:d.id,created:when()});audit(next,'CARICO_DOCUMENTO',{documentId:d.id,lines:lines.length})});say('Carico registrato una sola volta.');}
async function openOriginal(docId){await ready;const d=state.documents.find(d=>d.id===docId),f=state.files.find(f=>f.id===d?.fileId);if(!f)throw Error('Originale non trovato');const bytes=decode(f.base64),safeType=new TextDecoder().decode(bytes.subarray(0,5))==='%PDF-'?'application/pdf':/^image\/(?:png|jpeg|webp|bmp)$/.test(f.type)?f.type:'application/octet-stream';const url=URL.createObjectURL(new Blob([bytes],{type:safeType})),a=document.createElement('a');a.href=url;a.download=f.name;a.target='_blank';a.rel='noopener';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function build(){const section=$('magazzino');section.innerHTML='<h2>Articoli e magazzino</h2><p class="hint">Catalogo e giacenze distinti. Un preventivo o una Di.Co. non scaricano materiali.</p><div class="actions"><button id="warehouse-new" type="button">+ Nuovo articolo</button><a class="btn" href="#importazioni">Importa listini e documenti</a></div><label>Cerca codice, marca o descrizione<input id="warehouse-search" type="search"></label><div id="warehouse-editor" class="panel" hidden></div><div id="warehouse-list"></div><details class="panel"><summary><b>Movimenti e rettifiche</b></summary><div id="warehouse-movements"></div></details>';
 $('importazioni').innerHTML='<h2>Importazioni e archivio aziendale</h2><div id="import-processes" class="import-processes" role="group" aria-label="Processi aziendali"></div><div id="import-guide" class="panel"></div><p class="hint">Carica uno o più file, una cartella o uno ZIP. Il documento viene analizzato per contenuto. Originali e collegamenti sono conservati. XML, CSV e tabelle strutturate consentono estrazione precisa; PDF e scansioni richiedono controllo dei dati letti.</p><details class="panel"><summary><b>Profilo I.T.E. e riconoscimento acquisti / vendite</b></summary><div id="import-company-source"></div><button type="button" id="import-company-recover" class="secondary">Completa i campi vuoti con i dati Windows</button><form id="import-settings" class="grid"><label>Partita IVA I.T.E.<input name="companyVat" maxlength="13"></label><label>Codice fiscale I.T.E.<input name="companyCF" maxlength="16"></label><label>Ragione sociale<input name="companyName"></label><label>Indirizzo azienda<input name="companyAddress"></label><label>Telefono<input name="companyPhone" type="tel"></label><label>Email<input name="companyEmail" type="email"></label><button type="submit">Salva profilo azienda</button></form></details><div class="actions"><label class="touch-file-picker">Importa documenti<input id="import-files" type="file" multiple accept=".xml,.pdf,.csv,.tsv,.xlsx,.xls,.ods,.zip,.png,.jpg,.jpeg,.webp,.bmp,.tif,.tiff,.txt"></label><label class="touch-file-picker">Importa cartella<input id="import-folder" type="file" multiple webkitdirectory></label></div><p class="hint">PDF, OCR, Excel e ZIP usano componenti inclusi nel gestionale. Analisi sul dispositivo: i documenti non vengono inviati a servizi IA. Massimo 500 file, 20 MB per file e 100 MB per lotto.</p><p id="import-status" role="status" aria-live="polite"></p><div id="import-queue"></div><div class="actions"><button type="button" id="import-apply" disabled>Registra le schede selezionate</button><button type="button" id="import-clear" class="secondary">Annulla anteprima</button></div><div class="panel"><h3>Archivio e sottocartelle</h3><p class="hint">Processo / categoria / anno / cliente o azienda / cantiere. Puoi aggiungere una sottocartella in ogni scheda. I filtri non spostano né eliminano gli originali.</p><div class="grid"><label>Categoria<select id="import-category"><option value="">Tutte le categorie</option>'+types.map(t=>'<option>'+esc(t)+'</option>').join('')+'</select></label><label>Cerca documento o soggetto<input id="import-search" type="search"></label></div><div id="import-archive"></div></div><details class="panel"><summary><b>Apprendimento locale delle classificazioni</b></summary><p class="hint">Vengono ricordate solo le regole che scegli dopo aver verificato l’anteprima. I suggerimenti vanno applicati con il comando dedicato; importi, firme, esiti delle prove e prezzi non vengono appresi.</p><div id="import-learning-list"></div></details><details class="panel"><summary><b>Collegamento PC e iPad</b></summary><p>Archivio locale a questo browser. Il trasferimento con backup completo è disponibile in Backup e aggiornamenti. La sincronizzazione automatica con il database Windows non è ancora collegata.</p><a class="btn" href="#backup">Apri Backup e aggiornamenti</a></details><details class="panel"><summary><b>Registro importazioni</b></summary><div id="import-log"></div></details>';
 $('import-processes').onclick=e=>{const b=e.target.closest('[data-process]');if(b)selectProcess(b.dataset.process)}; $('import-company-source').innerHTML='<p><b>'+esc(companySource.companyName)+'</b><br>'+esc(companySource.companyAddress)+'<br>P.IVA '+esc(companySource.companyVat)+' · '+esc(companySource.companyPhone)+'<br>'+esc(companySource.companyEmail)+'</p><small>Fonte: profilo azienda del Gestionale Windows 2.7.5. Eventuali dati già compilati restano conservati.</small>';$('import-company-recover').onclick=()=>mutate(next=>{for(const [k,v] of Object.entries(companySource))if(!String(next.settings[k]||'').trim())next.settings[k]=v;audit(next,'RECUPERO_PROFILO_WINDOWS',{source:'unified_modules.py / COMPANY_DEFAULTS'})}).then(()=>{for(const [k,v] of Object.entries(state.settings))if($('import-settings').elements[k])$('import-settings').elements[k].value=v;say('Dati azienda recuperati. I campi già compilati sono conservati. Rianalizza i file per aggiornare acquisti / vendite.');}).catch(e=>say(e.message));$('import-learning-list').onclick=e=>{const b=e.target.closest('[data-forget-rule]');if(b)mutate(next=>{next.settings.documentRules=(next.settings.documentRules||[]).filter(r=>r.key!==b.dataset.forgetRule);audit(next,'DIMENTICA_CLASSIFICAZIONE',{key:b.dataset.forgetRule})}).then(()=>say('Regola rimossa; documenti e originali conservati.')).catch(e=>say(e.message));};const archive=document.createElement('div');archive.id='commerce-documents-panel';archive.className='panel';$('documenti').append(archive);
 $('warehouse-new').onclick=()=>articleEdit();$('warehouse-search').oninput=render;$('import-search').oninput=render;$('import-category').onchange=render;$('import-apply').onclick=()=>applyQueue().catch(e=>{say('Registrazione non completata: '+e.message);$('import-status').scrollIntoView({block:'nearest'});});$('import-clear').onclick=()=>{queue=[];drawQueue();say('Anteprima annullata: nessun dato registrato.')};for(const key of ['import-files','import-folder'])$(key).onchange=e=>{const files=[...e.target.files];e.target.value='';choose(files).catch(e=>say('Importazione non completata: '+e.message))};
 $('import-queue').addEventListener('change',e=>{const el=e.target;if(el.matches('[data-q="clientId"],[data-q="propertyId"],[data-q="plantId"]')){readQueue();const d=queue[Number(el.closest('[data-queue]')?.dataset.queue)];if(!d)return;if(el.dataset.q==='clientId'){d.propertyId='';d.plantId='';d.deviceId=''}else if(el.dataset.q==='propertyId'){d.plantId='';d.deviceId=''}else d.deviceId='';drawQueue()}});
 $('import-queue').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;readQueue();if(b.dataset.learnApply!==undefined){const d=queue[Number(b.dataset.learnApply)],r=d.learningSuggestion;if(r){if(d.sourceType)return;if(d.type==='Articoli'&&r.type==='Articoli')d.catalogOptions={...d.catalogOptions,...copy(r.catalogOptions||{})};else if(d.type==='Da verificare'&&!['Anagrafiche','Articoli'].includes(r.type))d.type=r.type;else{say('Il documento ha già una categoria riconosciuta: conserva la lettura originale o cambia categoria manualmente.');return}d.reviewed=false;inferLinks(d);drawQueue();say('Suggerimento applicato. Controlla i dati prima di registrare.');}return;}if(b.dataset.catalogPage){const d=queue[Number(b.dataset.catalogIndex)];d.previewPage=(d.previewPage||0)+Number(b.dataset.catalogPage);drawQueue()}if(b.dataset.reanalyze!==undefined)reanalyze(Number(b.dataset.reanalyze)).catch(e=>say(e.message));if(b.dataset.mapApply!==undefined){const i=Number(b.dataset.mapApply),d=queue[i],fields=d.mapping||[],selected=fields.filter(Boolean);if(!selected.includes('code')||!selected.includes('description')||new Set(selected).size!==selected.length){say('Associa una sola colonna Codice e una sola Descrizione; gli altri campi sono facoltativi e non devono essere duplicati.');return}try{const docs=analyzeMatrix(d.tableRows,d.tableAnalysis.sheetName,d.tableAnalysis.sourceRow,{headerRow:Number(d.mappingHeader||0),fields});for(const item of docs){item.file=d.file;item.fileId=d.fileId;item.sourceName=d.sourceName;item.created=d.created;item.sourceIndex=d.sourceIndex;item.subjectId=d.subjectId}if(d.existingId){docs[0].existingId=d.existingId;docs[0].id=d.id}queue.splice(i,1,...docs);drawQueue();say('Colonne applicate: '+docs.reduce((n,x)=>n+x.lines.length,0)+' articoli estratti.')}catch(e){say(e.message)}}});
$('import-queue').addEventListener('change',e=>{readQueue();if(e.target.dataset.catalogOption){const d=queue[Number(e.target.dataset.catalogIndex)];d.catalogOptions=d.catalogOptions||{};d.catalogOptions[e.target.dataset.catalogOption]=e.target.value;prepareWindowsCatalog(d);drawQueue();return;}if(e.target.dataset.mappingHeader!==undefined){queue[Number(e.target.dataset.mappingHeader)].mappingHeader=Number(e.target.value);drawQueue();return}if(e.target.dataset.mapCol!==undefined){const d=queue[Number(e.target.dataset.mapIndex)];d.mapping=d.mapping||[];d.mapping[Number(e.target.dataset.mapCol)]=e.target.value;return}const box=e.target.closest('[data-queue]');if(!box)return;const d=queue[Number(box.dataset.queue)];if(e.target.dataset.q==='clientId'){d.propertyId=d.siteId=d.plantId=d.deviceId=d.jobId='';drawQueue()}if(e.target.dataset.q==='propertyId'){d.plantId=d.deviceId='';drawQueue()}if(e.target.dataset.q==='plantId'){d.deviceId='';drawQueue()}if(e.target.dataset.q==='type'){if(d.seller){d.party=copy(/vendita|DDT emesso/.test(d.type)?d.buyer:d.seller)}drawQueue()}});
 $('import-settings').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),settings=Object.fromEntries(f);if(settings.companyVat&&!/^\d{11}$/.test(tax(settings.companyVat))||settings.companyCF&&!/^(?:\d{11}|[A-Z0-9]{16})$/.test(tax(settings.companyCF))){say('Controlla P.IVA e codice fiscale.');return}mutate(next=>{next.settings={...next.settings,...Object.fromEntries(Object.entries(settings).map(([k,v])=>[k,String(v).trim()])),companyVat:tax(settings.companyVat),companyCF:tax(settings.companyCF)};audit(next,'DATI_RICONOSCIMENTO_AZIENDA',{})}).then(()=>say('Dati azienda salvati. Ora puoi importare o rianalizzare i documenti.')).catch(e=>say(e.message))};
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.articleEdit)articleEdit(d.articleEdit);if(d.stockEdit)stockEdit(d.stockEdit);if(d.importOpen)openOriginal(d.importOpen).catch(e=>say(e.message));if(d.importEdit)editDocument(d.importEdit).catch(e=>say(e.message));if(d.importStock)stockDocument(d.importStock).catch(e=>{say(e.message);alert(e.message)})});
 const oldProfile=ITEProfile.open;ITEProfile.open=function(clientId){profileId=String(clientId);oldProfile(clientId);setTimeout(renderLinked,50)};for(const el of [$('worksite-detail'),$('profilo-cliente')])if(el)new MutationObserver(()=>{if(!$('commerce-site-links')||!$('commerce-client-links'))renderLinked()}).observe(el,{childList:true});
 const oldRemove=ITE.remove;ITE.remove=async(k,key)=>{await ready;await refresh();const field={clienti:['subjectId','clientId'],immobili:['propertyId'],cantieri:['siteId'],impianti:['plantId'],apparecchiature:['deviceId'],interventi:['jobId']}[k]||[];if(state.documents.some(d=>field.some(f=>same(d[f],key))||k==='clienti'&&(d.subjectIds||[]).some(x=>same(x,key)))||k==='cantieri'&&state.movements.some(m=>same(m.siteId,key))||k==='clienti'&&state.articles.some(a=>same(a.supplierId,key)))return alert('Elemento collegato a documenti o magazzino: conserva lo storico e verifica i collegamenti prima di eliminarlo.');return oldRemove(k,key)};
 window.addEventListener('ite-pagechange',()=>{if(['magazzino','importazioni','documenti','scheda-cantiere','scheda-cliente'].includes(ITERouter.current()))ready.then(()=>refresh()).then(render).catch(e=>say(e.message))});
}
