(()=>{'use strict';
const VERSION='3.0.73',DB='ITE_BACKUP_HISTORY_V1',TABLE='copies';let database=null,working=null,selected=null;
const panel=document.createElement('div');panel.className='panel';panel.id='backup-history';panel.innerHTML='<h3>Storico backup completi</h3><p class="hint">Copie datate con versione, dati e allegati. Una copia automatica al giorno e prima degli aggiornamenti. Queste copie sono nello stesso dispositivo: conserva anche un backup scaricato nell’app File o su un altro supporto.</p><div class="actions"><button type="button" id="history-create">Crea copia adesso</button><button type="button" class="secondary" id="history-refresh">Aggiorna elenco</button></div><p id="history-status" role="status" aria-live="polite"></p><div id="history-list"></div><div id="history-preview" hidden></div>';
document.getElementById('backup').insertBefore(panel,document.getElementById('backup').children[1]);
const $=id=>document.getElementById(id),say=s=>$('history-status').textContent=s;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>JSON.parse(JSON.stringify(v));
function canonical(v){if(Array.isArray(v))return '['+v.map(canonical).join(',')+']';if(v&&typeof v==='object')return '{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+canonical(v[k])).join(',')+'}';return JSON.stringify(v)}
async function hash(text){if(!crypto.subtle)throw Error('Verifica integrità non disponibile in questo browser.');const bytes=new TextEncoder().encode(text);return [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('')}
function open(){if(database)return Promise.resolve(database);return new Promise((resolve,reject)=>{const q=ITEVault.openDatabase(DB,1);q.onupgradeneeded=()=>{q.result.createObjectStore(TABLE,{keyPath:'id'});q.result.createObjectStore('meta',{keyPath:'id'})};q.onsuccess=()=>{database=q.result;database.onversionchange=()=>{database.close();database=null};resolve(database)};q.onerror=()=>reject(q.error);q.onblocked=()=>reject(Error('Chiudi le altre schede del gestionale e riprova.'))})}
async function operation(table,mode,fn){const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction(table,mode);let req;try{req=fn(tx.objectStore(table))}catch(e){tx.abort();reject(e);return}tx.oncomplete=()=>resolve(req?.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Salvataggio interrotto'))})}
const list=()=>operation(TABLE,'readonly',s=>s.getAll());
async function read(id){const record=await operation(TABLE,'readonly',s=>s.get(id));if(!record||await hash(record.payload)!==record.checksum)throw Error('Copia danneggiata o incompleta: ripristino bloccato.');const b=JSON.parse(record.payload);validate(b);return {record,backup:b}}
function validate(b){if(b.commerce&&window.ITECommerce)ITECommerce.validate(b.commerce,b.data);if(b.format!=='ITE-complete'||b.schema!==1||!ITE.validate(b.data)||!Array.isArray(b.docs))throw Error('Backup non valido.');ITEContacts.validateLinks(b.data);ITEAgenda.validateDatabase(b.data);for(const [child,key,parent] of [['immobili','client_id','clienti'],['impianti','immobile_id','immobili'],['apparecchiature','impianto_id','impianti'],['interventi','apparecchiatura_id','apparecchiature']])for(const r of b.data[child]||[])if(r[key]&&!b.data[parent].some(p=>String(p.id)===String(r[key])))throw Error('Collegamento mancante: '+child);const ids=new Set();for(const d of b.docs){if(typeof d.id!=='string'||!/^[A-Za-z0-9_-]+$/.test(d.id)||ids.has(d.id)||typeof d.base64!=='string'||!b.data[d.parentType]?.some(r=>String(r.id)===String(d.parentId))||(d.subjectId&&!b.data.clienti.some(r=>String(r.id)===String(d.subjectId)))||(d.siteId&&!b.data.cantieri?.some(r=>String(r.id)===String(d.siteId)))||(d.date&&!ITEDocs.validDate(d.date))||(d.expires&&!ITEDocs.validDate(d.expires))||atob(d.base64).length!==d.size)throw Error('Allegato incompleto o collegamento non valido.');ids.add(d.id)}}
function counts(b){return {...Object.fromEntries(Object.entries(b.data).map(([k,v])=>[k,v.length])),allegati:b.docs.length+(b.commerce?.files?.length||0),articoli:b.commerce?.articles?.length||0,movimenti_magazzino:b.commerce?.movements?.length||0,documenti_importati:b.commerce?.documents?.length||0}}
function countText(c){return Object.entries(c).map(([k,v])=>k+': '+v).join(' · ')}
function today(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
async function capture(reason){const start=canonical(ITE.snapshot()),backup=await ITEBackup.pack();if(start!==canonical(ITE.snapshot())||start!==canonical(backup.data))throw Error('Dati modificati durante il backup: riprova.');validate(backup);const payload=JSON.stringify(backup),checksum=await hash(payload),id='b_'+Date.now()+'_'+crypto.randomUUID();const record={id,created:backup.created,day:today(),version:VERSION,reason,counts:counts(backup),payload,checksum};await operation(TABLE,'readwrite',s=>s.add(record));await read(id);return record}
async function create(reason='Manuale'){if(working)return working;working=(async()=>{const record=await capture(reason);await render();say('Copia completa salvata e verificata · '+countText(record.counts));return record})();try{return await working}finally{working=null}}
async function render(){const records=(await list()).sort((a,b)=>b.created.localeCompare(a.created));$('history-list').innerHTML=records.length?records.map(r=>'<div class="item"><strong>'+esc(new Date(r.created).toLocaleString('it-IT'))+' · '+esc(r.version)+'</strong><p>'+esc(r.reason)+'</p><p class="hint">'+esc(countText(r.counts))+'</p><button type="button" data-history-preview="'+esc(r.id)+'">Anteprima / ripristina</button><button type="button" class="secondary" data-history-export="'+esc(r.id)+'">Scarica copia</button></div>').join(''):'<p>Nessuna copia interna ancora salvata.</p>'}
async function preview(id){selected=null;const {record,backup}=await read(id),current=await ITEBackup.pack();const box=$('history-preview');box.innerHTML='<h4>Copia del '+esc(new Date(record.created).toLocaleString('it-IT'))+' · '+esc(record.version)+'</h4><p>Archivio attuale: '+esc(countText(counts(current)))+'</p><p>Copia selezionata: '+esc(countText(counts(backup)))+'</p><p>Il ripristino sostituisce l’intero archivio con questa copia, compresi gli allegati. Prima vengono conservati e scaricati i dati attuali.</p><div class="actions"><button type="button" id="history-restore">Ripristina questa copia</button><button type="button" class="secondary" id="history-close">Chiudi anteprima</button></div>';box.hidden=false;selected=id;$('history-close').onclick=()=>{selected=null;box.hidden=true};$('history-restore').onclick=()=>restoreSelected().catch(e=>say(e.message));box.scrollIntoView({block:'nearest'})}
function downloadText(text,name){const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function exportCopy(id){const {record}=await read(id);downloadText(JSON.stringify(ITEVault.sealBackup(JSON.parse(record.payload))),'ITE_backup_'+record.version+'_'+record.created.replace(/[:.]/g,'-')+'.json');say('Download preparato: verifica il file nell’app File / Download.')}
function busy(){return window.ITECommerce?.busy?.()||['editor','docs-form','appointment-form','extra-editor','warehouse-editor'].some(id=>{const e=$(id);return e&&!e.hidden})}
async function restoreSelected(){if(!selected)throw Error('Seleziona una copia.');if(busy())throw Error('Salva o annulla il modulo aperto prima del ripristino.');const {record}=await read(selected);await ITEBackup.restore({files:[{text:async()=>record.payload}],value:''})}
// L’impronta esclude data e versione della copia: confronta soltanto dati e allegati.
const fingerprint=b=>hash(canonical({data:b.data,commerce:b.commerce||null,docs:[...b.docs].sort((a,b)=>a.id.localeCompare(b.id))}));
const beforeUpdate=async()=>{if(busy())throw Error('Salva o annulla il modulo aperto prima di aggiornare.');const record=await create('Prima aggiornamento'),{backup}=await read(record.id);const mark={id:'pendingUpdate',version:VERSION,fingerprint:await fingerprint(backup)};await operation('meta','readwrite',s=>s.put(mark))};
async function automatic(){try{const pending=await operation('meta','readonly',s=>s.get('pendingUpdate'));if(pending){const current=await ITEBackup.pack();if(pending.fingerprint!==await fingerprint(current)){say('Controllo dopo aggiornamento: archivio diverso dalla copia precedente. Le copie restano disponibili; nessun ripristino automatico.');return}await operation('meta','readwrite',s=>s.delete('pendingUpdate'));say('Integrità dopo aggiornamento verificata: dati e allegati coincidono.')}const records=await list();if(!records.some(r=>r.day===today()&&r.version===VERSION))await create('Automatica giornaliera');else await render()}catch(e){say('Backup automatico non completato: '+e.message+'. Scarica un backup completo esterno.')}}
ITE.reset=()=>{say('Azzeramento demo disattivato per proteggere i dati.');alert('Azzeramento demo disattivato. I dati sono conservati.')};
ITE.importData=event=>{if(event?.target)event.target.value='';say('Importazione precedente disattivata. Usa Aggiorna dati con anteprima oppure Ripristina backup completo.')};
for(const e of document.querySelectorAll('[onclick="ITE.reset()"],[onclick*="import-file"]')){e.disabled=true;e.title='Disattivato per proteggere i dati';e.textContent+=' — disattivato'}
$('history-create').onclick=()=>create().catch(e=>say('Copia non salvata: '+e.message));$('history-refresh').onclick=()=>render().catch(e=>say(e.message));panel.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.historyPreview)preview(b.dataset.historyPreview).catch(e=>say(e.message));if(b?.dataset.historyExport)exportCopy(b.dataset.historyExport).catch(e=>say(e.message))});
window.ITEHistory={create,list,read,preview,exportCopy,beforeUpdate,automatic,restoreSelected,validate};
window.addEventListener('ite-pagechange',()=>{if(ITERouter.current()==='backup')render().catch(e=>say(e.message))});document.addEventListener('visibilitychange',()=>{if(!document.hidden)automatic()});window.addEventListener('pageshow',automatic);automatic();
})();
